CREATE OR REPLACE FUNCTION public.accept_invite(p_token_hash text, p_session_user bigint, p_name text, p_hash text, p_salt text)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare t public.auth_tokens%rowtype; v_user bigint; v_name text; grant_id text;
begin
 perform pg_advisory_xact_lock(194701,1);
 select * into t from public.auth_tokens where token_hash=p_token_hash and kind='invite' for update;
 if not found or t.used_at is not null or t.expires_at<=now() then raise exception 'Convite inválido ou expirado'; end if;
 select id into v_user from public.users where lower(email)=t.email;
 if v_user is not null then
  if p_session_user is distinct from v_user then raise exception 'Entre com a conta deste e-mail para aceitar o convite'; end if;
  if (select role from public.users where id=v_user)<>t.role then raise exception 'Essa pessoa já tem conta com outro papel'; end if;
 else
  if not public.valid_password_credentials(p_hash,p_salt) then raise exception 'Credencial inválida'; end if;
  v_name:=coalesce(nullif(btrim(coalesce(p_name,'')),''),t.payload->>'name');
  if coalesce(char_length(v_name),0) not between 2 and 120 then raise exception 'Informe seu nome'; end if;
  if t.role='doctor' and exists(select 1 from public.users where doctor_id=t.payload->>'doctorId') then raise exception 'Este médico já possui um acesso'; end if;
  insert into public.users(email,name,role,doctor_id,active,password_hash,password_salt,email_verified_at)
   values(t.email,v_name,t.role,case when t.role='doctor' then t.payload->>'doctorId' end,true,p_hash,p_salt,now()) returning id into v_user;
 end if;
 insert into public.organization_memberships(organization_id,user_id,role,active) values(t.organization_id,v_user,t.role,true)
  on conflict(organization_id,user_id) do update set role=excluded.role,active=true,updated_at=clock_timestamp();
 update public.users set active=true where id=v_user;
 perform set_config('rn.organization',t.organization_id::text,true);
 if t.role<>'general_manager' then
  for grant_id in select jsonb_array_elements_text(coalesce(t.payload->'agendaIds','[]'::jsonb)) loop
   insert into public.agenda_access(user_id,professional_id,organization_id) select v_user,grant_id,t.organization_id
    where exists(select 1 from public.doctors where id=grant_id and organization_id=t.organization_id)
      and not exists(select 1 from public.agenda_access where user_id=v_user and professional_id=grant_id);
  end loop;
  if t.role='doctor' and t.payload->>'doctorId' is not null and not exists(select 1 from public.agenda_access where user_id=v_user and professional_id=t.payload->>'doctorId') then
   insert into public.agenda_access(user_id,professional_id,organization_id) values(v_user,t.payload->>'doctorId',t.organization_id);
  end if;
 end if;
 update public.auth_tokens set used_at=now(),user_id=v_user where id=t.id;
 insert into public.directory_audit(actor_id,kind,record_id,before_data,after_data,organization_id)
  values(coalesce(t.created_by,v_user),'invite_accepted',v_user::text,null,jsonb_build_object('email',t.email,'role',t.role,'invite',t.id),t.organization_id);
 perform set_config('rn.organization','',true);
 return v_user;
end;$function$
;

CREATE OR REPLACE FUNCTION public.actor_organization_id(p_actor bigint)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare o uuid:=nullif(current_setting('rn.organization',true),'')::uuid; n integer; v uuid;
begin
 if o is not null then
  if public.membership_organization_ok(p_actor,o) then return o; end if;
  raise exception 'Acesso à organização negado';
 end if;
 select count(*),min(m.organization_id::text)::uuid into n,v from public.users u
  join public.organization_memberships m on m.user_id=u.id and m.active and m.role=u.role
  join public.organizations og on og.id=m.organization_id and og.active
  join public.accounts a on a.id=og.account_id and a.status='active'
  where u.id=p_actor and u.active;
 if n=1 then return v; end if;
 if n=0 then raise exception 'Acesso à organização negado'; end if;
 raise exception 'Selecione a organização';
end;$function$
;

CREATE OR REPLACE FUNCTION public.agenda_appointment_json(a appointments)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
 select jsonb_strip_nulls(jsonb_build_object('cancelledAt',public.agenda_iso(a.cancelled_at),'cancelReason',a.cancel_reason,
   'statusUpdatedAt',public.agenda_iso(a.status_updated_at),'suggestedByName',a.suggested_by_name,'suggestedByEmail',a.suggested_by_email,
   'insurance',a.insurance,'forma_cobranca',a.billing_method))
  ||jsonb_build_object('id',a.id,'doctorId',coalesce(a.professional_id,''),'anesthetistId',a.anesthetist_id,'patientId',coalesce(a.patient_id,''),
  'hospitalId',coalesce(a.hospital_id,''),'date',to_char(a.date,'YYYY-MM-DD'),'time',public.agenda_hhmi(a.time),'duration',a.duration_min,
  'status',a.status,'careType',a.care_type,'procedure',a.procedure,'guideExpiry',coalesce(a.guide_expiry,''),'procedureValue',a.procedure_value,
  'opme',a.opme,'reports',a.reports,'exams',a.exams,'notes',coalesce(a.notes,''),
  'rescheduleReason',coalesce(a.reschedule_reason,''),'suggestionReason',coalesce(a.suggestion_reason,''),
  'rescheduleHistory',coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('fromDate',r.from_date,'fromTime',r.from_time,
     'toDate',r.to_date,'toTime',r.to_time,'reason',r.reason,'proposedBy',r.proposed_by,'createdAt',r.proposed_at)) order by r.position)
   from public.appointment_reschedules r where r.appointment_id=a.id),'[]'::jsonb))
$function$
;

CREATE OR REPLACE FUNCTION public.agenda_block_json(b schedule_blocks)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
 select jsonb_build_object('id',b.id,'professionalId',b.professional_id,'hospitalId',null,'date',to_char(b.date,'YYYY-MM-DD'),
  'start',public.agenda_hhmi(b.start_time),'end',public.agenda_hhmi(b.end_time),'reason',b.reason)
$function$
;

CREATE OR REPLACE FUNCTION public.agenda_hhmi(t time without time zone)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$ select to_char(t,'HH24:MI') $function$
;

