 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$ select extract(hour from t)::int*60+extract(minute from t)::int $function$
;

CREATE OR REPLACE FUNCTION public.agenda_patient_json(p patients)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
 select jsonb_build_object('id',p.id,'doctorId',p.owner_professional_id,'name',p.name,'cpf',coalesce(p.cpf,''),
  'phone',coalesce(p.phone,''),'email',coalesce(p.email,''),'insurance',coalesce(p.insurance,''),'cardNumber',coalesce(p.card_number,''),
  'address',coalesce(p.address,''),'addressZip',coalesce(p.address_zip,''),'addressNumber',coalesce(p.address_number,''),
  'addressComplement',coalesce(p.address_complement,''),'addressNeighborhood',coalesce(p.address_neighborhood,''),
  'addressCity',coalesce(p.address_city,''),'addressState',coalesce(p.address_state,''),
  'newborn',p.newborn,'guardianName',coalesce(p.guardian_name,''),
  'created_at',public.agenda_iso(p.created_at),'created_by',p.created_by,'updated_at',public.agenda_iso(p.updated_at),'updated_by',p.updated_by)
$function$
;

CREATE OR REPLACE FUNCTION public.agenda_revision(p_actor bigint)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
begin
 return (select revision from public.agenda_settings where organization_id=public.require_rn_agenda_actor_organization(p_actor));
end;$function$
;

CREATE OR REPLACE FUNCTION public.agenda_revision(p_actor bigint, p_org uuid)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ begin perform public.use_organization(p_actor,p_org); return public.agenda_revision(p_actor); end;$function$
;

CREATE OR REPLACE FUNCTION public.agenda_row_bases(p_actor bigint, p_revision timestamp with time zone, p_keys jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare org uuid:=public.require_rn_agenda_actor_organization(p_actor);
begin
 return coalesce((select jsonb_agg(jsonb_build_object('entity',k.entity,'id',k.id,
   'currentVersion',public.agenda_row_version_of(k.entity,k.id,org),
   'baseVersion',base.row_version,'base',base.data))
  from jsonb_to_recordset(coalesce(p_keys,'[]'::jsonb)) k(entity text,id text)
  left join lateral (select v.row_version,v.data from public.agenda_row_versions v
    where v.organization_id=org and v.entity=k.entity and v.row_id=k.id and v.revision<=p_revision
    order by v.revision desc,v.row_version desc limit 1) base on true),'[]'::jsonb);
end;$function$
;

CREATE OR REPLACE FUNCTION public.agenda_row_bases(p_actor bigint, p_revision timestamp with time zone, p_keys jsonb, p_org uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ begin perform public.use_organization(p_actor,p_org); return public.agenda_row_bases(p_actor,p_revision,p_keys); end;$function$
;

CREATE OR REPLACE FUNCTION public.agenda_row_json(p_entity text, p_id text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$ select public.agenda_row_json(p_entity,p_id,public.current_organization_id()) $function$
;

CREATE OR REPLACE FUNCTION public.agenda_row_json(p_entity text, p_id text, p_org uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
 case p_entity
  when 'patients' then select public.agenda_patient_json(x) into result from public.patients x where id=p_id and organization_id=p_org;
  when 'appointments' then select public.agenda_appointment_json(x)||jsonb_build_object('_cancelled',x.cancelled_at is not null,'_archived',x.archived_at is not null) into result from public.appointments x where id=p_id and organization_id=p_org;
  when 'hospitals' then select public.agenda_hospital_json(x)||jsonb_build_object('_archived',x.archived_at is not null) into result from public.hospitals x where id=p_id and organization_id=p_org;
  when 'scheduleBlocks' then select public.agenda_block_json(x) into result from public.schedule_blocks x where id=p_id and organization_id=p_org;
  when 'schedulingRules' then select public.agenda_rule_json(x) into result from public.scheduling_rules x where id=p_id and organization_id=p_org;
  else raise exception 'Entidade inválida';
 end case;
 return result;
end;$function$
;

CREATE OR REPLACE FUNCTION public.agenda_row_version_of(p_entity text, p_id text)
 RETURNS integer
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$ select public.agenda_row_version_of(p_entity,p_id,public.current_organization_id()) $function$
;

CREATE OR REPLACE FUNCTION public.agenda_row_version_of(p_entity text, p_id text, p_org uuid)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare v integer;
begin
 case p_entity
  when 'patients' then select row_version into v from public.patients where id=p_id and organization_id=p_org;
  when 'appointments' then select row_version into v from public.appointments where id=p_id and organization_id=p_org;
  when 'hospitals' then select row_version into v from public.hospitals where id=p_id and organization_id=p_org;
  when 'scheduleBlocks' then select row_version into v from public.schedule_blocks where id=p_id and organization_id=p_org;
  when 'schedulingRules' then select row_version into v from public.scheduling_rules where id=p_id and organization_id=p_org;
  else raise exception 'Entidade inválida';
 end case;
 return v;
end;$function$
;

CREATE OR REPLACE FUNCTION public.agenda_rule_json(r scheduling_rules)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
 select jsonb_build_object('id',r.id,'professionalId',r.professional_id,'hospitalId',r.hospital_id,'name',r.name,'severity',r.severity,
  'weekday',coalesce(r.weekday::text,''),'occurrence',coalesce(r.occurrence,''),
  'start',coalesce(public.agenda_hhmi(r.start_time),''),'end',coalesce(public.agenda_hhmi(r.end_time),''),
  'maxPatients',r.max_patients,'procedureContains',r.procedure_contains,
  'preferredTimes',array_to_string(array(select public.agenda_hhmi(x) from unnest(r.preferred_times) x),','),
  'forbiddenTimes',array_to_string(array(select public.agenda_hhmi(x) from unnest(r.forbidden_times) x),','),
  'blockAllDay',r.block_all_day,'enabled',r.enabled)
$function$
;

CREATE OR REPLACE FUNCTION public.agenda_state_json(p_org uuid, p_since date, p_after timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
 select jsonb_build_object('revision',to_char(s.revision at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'state',jsonb_build_object(
  'schemaVersion',7,
  'settings',jsonb_build_object('workStart',to_char(s.work_start,'HH24:MI'),'workEnd',to_char(s.work_end,'HH24:MI')),
  'professionals',coalesce((select jsonb_agg(coalesce(d.details,'{}'::jsonb)||jsonb_build_object('id',d.id,'name',d.name,'crm',coalesce(d.crm,''),
     'specialty',coalesce(d.specialty,''),'category',d.category,'active',d.active,'scheduling_enabled',d.scheduling_enabled,
     'billing_enabled',d.billing_enabled,'invoice_enabled',d.invoice_enabled,
     'agendaEnabled',coalesce(a.active,false) and d.scheduling_enabled,'agendaSettings',coalesce(a.settings,'{}'::jsonb)) order by d.name)
   from public.doctors d left join public.doctor_agendas a on a.doctor_id=d.id where d.organization_id=p_org),'[]'::jsonb),
  'hospitals',coalesce((select jsonb_agg(jsonb_build_object('id',h.id,'name',h.name,'abbreviation',coalesce(h.abbreviation,'')) order by h.name)
   from public.hospitals h where h.organization_id=p_org and h.archived_at is null and (p_after is null or h.updated_at>p_after-interval '2 seconds')),'[]'::jsonb),
  'patients',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'doctorId',p.owner_professional_id,'name',p.name,'cpf',coalesce(p.cpf,''),
     'phone',coalesce(p.phone,''),'email',coalesce(p.email,''),'insurance',coalesce(p.insurance,''),'cardNumber',coalesce(p.card_number,''),
     'address',coalesce(p.address,''),'addressZip',coalesce(p.address_zip,''),'addressNumber',coalesce(p.address_number,''),
     'addressComplement',coalesce(p.address_complement,''),'addressNeighborhood',coalesce(p.address_neighborhood,''),
     'addressCity',coalesce(p.address_city,''),'addressState',coalesce(p.address_state,''),
     'newborn',p.newborn,'guardianName',coalesce(p.guardian_name,''),
     'created_at',to_char(p.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'created_by',p.created_by,
     'updated_at',to_char(p.updated_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'updated_by',p.updated_by) order by p.name,p.id)
   from public.patients p where p.organization_id=p_org and p.archived_at is null and (p_after is null or p.updated_at>p_after-interval '2 seconds')),'[]'::jsonb),
  'appointments',coalesce((select jsonb_agg(x.j order by x.date,x.time,x.id) from (
    select a.date,a.time,a.id,jsonb_strip_nulls(jsonb_build_object(
      'cancelledAt',to_char(a.cancelled_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'cancelReason',a.cancel_reason,
      'statusUpdatedAt',to_char(a.status_updated_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'suggestedByName',a.suggested_by_name,
      'suggestedByEmail',a.suggested_by_email,'insurance',a.insurance,'forma_cobranca',a.billing_method))
     ||jsonb_build_object('id',a.id,'doctorId',coalesce(a.professional_id,''),'anesthetistId',a.anesthetist_id,'patientId',coalesce(a.patient_id,''),
      'hospitalId',coalesce(a.hospital_id,''),'date',to_char(a.date,'YYYY-MM-DD'),'time',to_char(a.time,'HH24:MI'),'duration',a.duration_min,
      'status',a.status,'careType',a.care_type,'procedure',a.procedure,'guideExpiry',coalesce(a.guide_expiry,''),'procedureValue',a.procedure_value,
      'opme',a.opme,'reports',a.reports,'exams',a.exams,'notes',coalesce(a.notes,''),
      'rescheduleReason',coalesce(a.reschedule_reason,''),'suggestionReason',coalesce(a.suggestion_reason,''),
      'rescheduleHistory',coalesce(rh.items,'[]'::jsonb)) j
    from public.appointments a
    left join lateral (select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('fromDate',r.from_date,'fromTime',r.from_time,
       'toDate',r.to_date,'toTime',r.to_time,'reason',r.reason,'proposedBy',r.proposed_by,'createdAt',r.proposed_at)) order by r.position) items
      from public.appointment_reschedules r where r.appointment_id=a.id) rh on true
    where a.organization_id=p_org and a.cancelled_at is null and a.archived_at is null and (p_since is null or a.date>=p_since)
      and (p_after is null or a.updated_at>p_after-interval '2 seconds' or exists (select 1 from public.appointment_reschedules r2 where r2.appointment_id=a.id and r2.updated_at>p_after-interval '2 seconds'))) x),'[]'::jsonb),
  'cancelledAppointments',coalesce((select jsonb_agg(x.j order by x.cancelled_at,x.id) from (
    select a.cancelled_at,a.id,jsonb_strip_nulls(jsonb_build_object(
      'cancelledAt',to_char(a.cancelled_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'cancelReason',a.cancel_reason,
      'statusUpdatedAt',to_char(a.status_updated_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'suggestedByName',a.suggested_by_name,
      'suggestedByEmail',a.suggested_by_email,'insurance',a.insurance,'forma_cobranca',a.billing_method))
     ||jsonb_build_object('id',a.id,'doctorId',coalesce(a.professional_id,''),'anesthetistId',a.anesthetist_id,'patientId',coalesce(a.patient_id,''),
      'hospitalId',coalesce(a.hospital_id,''),'date',to_char(a.date,'YYYY-MM-DD'),'time',to_char(a.time,'HH24:MI'),'duration',a.duration_min,
      'status',a.status,'careType',a.care_type,'procedure',a.procedure,'guideExpiry',coalesce(a.guide_expiry,''),'procedureValue',a.procedure_value,
      'opme',a.opme,'reports',a.reports,'exams',a.exams,'notes',coalesce(a.notes,''),
      'rescheduleReason',coalesce(a.reschedule_reason,''),'suggestionReason',coalesce(a.suggestion_reason,''),
      'rescheduleHistory',coalesce(rh.items,'[]'::jsonb)) j
    from public.appointments a
    left join lateral (select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('fromDate',r.from_date,'fromTime',r.from_time,
       'toDate',r.to_date,'toTime',r.to_time,'reason',r.reason,'proposedBy',r.proposed_by,'createdAt',r.proposed_at)) order by r.position) items
      from public.appointment_reschedules r where r.appointment_id=a.id) rh on true
    where a.organization_id=p_org and a.cancelled_at is not null and a.archived_at is null and (p_since is null or a.date>=p_since)
      and (p_after is null or a.updated_at>p_after-interval '2 seconds' or exists (select 1 from public.appointment_reschedules r2 where r2.appointment_id=a.id and r2.updated_at>p_after-interval '2 seconds'))) x),'[]'::jsonb),
  'patientHistory',coalesce((select jsonb_agg(jsonb_build_object('id',h.id,'patientId',h.patient_id,'appointmentId',h.appointment_id,'type',h.type,'text',h.text,
     'at',to_char(h.at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) order by h.at,h.id)
   from public.patient_history_events h
   where h.organization_id=p_org and (p_since is null or h.at>=p_since::timestamptz or exists (select 1 from public.appointments a
     where a.organization_id=p_org and a.id=h.appointment_id and a.date>=p_since))
     and (p_after is null or h.updated_at>p_after-interval '2 seconds')),'[]'::jsonb),
  'schedulingRules',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'professionalId',r.professional_id,'hospitalId',r.hospital_id,'name',r.name,'severity',r.severity,
     'weekday',coalesce(r.weekday::text,''),'occurrence',coalesce(r.occurrence,''),
     'start',coalesce(to_char(r.start_time,'HH24:MI'),''),'end',coalesce(to_char(r.end_time,'HH24:MI'),''),
     'maxPatients',r.max_patients,'procedureContains',r.procedure_contains,
     'preferredTimes',array_to_string(array(select to_char(t,'HH24:MI') from unnest(r.preferred_times) t),','),
     'forbiddenTimes',array_to_string(array(select to_char(t,'HH24:MI') from unnest(r.forbidden_times) t),','),
     'blockAllDay',r.block_all_day,'enabled',r.enabled) order by r.created_at,r.id)
   from public.scheduling_rules r where r.organization_id=p_org),'[]'::jsonb),
  'scheduleBlocks',coalesce((select jsonb_agg(jsonb_build_object('id',b.id,'professionalId',b.professional_id,'hospitalId',null,'date',to_char(b.date,'YYYY-MM-DD'),
     'start',to_char(b.start_time,'HH24:MI'),'end',to_char(b.end_time,'HH24:MI'),'reason',b.reason) order by b.date,b.start_time,b.id)
   from public.schedule_blocks b where b.organization_id=p_org),'[]'::jsonb)
 ))
 ||case when p_after is null then '{}'::jsonb else jsonb_build_object('delta',true,'order',jsonb_build_object(
  'hospitals',coalesce((select jsonb_agg(h.id order by h.name) from public.hospitals h where h.organization_id=p_org and h.archived_at is null),'[]'::jsonb),
  'patients',coalesce((select jsonb_agg(p.id order by p.name,p.id) from public.patients p where p.organization_id=p_org and p.archived_at is null),'[]'::jsonb),
  'appointments',coalesce((select jsonb_agg(a.id order by a.date,a.time,a.id) from public.appointments a
    where a.organization_id=p_org and a.cancelled_at is null and a.archived_at is null and (p_since is null or a.date>=p_since)),'[]'::jsonb),
  'cancelledAppointments',coalesce((select jsonb_agg(a.id order by a.cancelled_at,a.id) from public.appointments a
    where a.organization_id=p_org and a.cancelled_at is not null and a.archived_at is null and (p_since is null or a.date>=p_since)),'[]'::jsonb),
  'patientHistory',coalesce((select jsonb_agg(h.id order by h.at,h.id) from public.patient_history_events h
    where h.organization_id=p_org and (p_since is null or h.at>=p_since::timestamptz or exists (select 1 from public.appointments a
      where a.organization_id=p_org and a.id=h.appointment_id and a.date>=p_since))),'[]'::jsonb))) end
 from public.agenda_settings s where s.organization_id=p_org
$function$
;

CREATE OR REPLACE FUNCTION public.agenda_sync_signal(p_token_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
 v_session jsonb:=public.session_context(p_token_hash);
 v_id bigint; v_role text; v_org uuid; v_agendas text[]; v_revision timestamptz; v_workflow timestamptz;
begin
 if v_session is null then return null; end if;
 v_id:=(v_session->'account'->>'id')::bigint; v_role:=v_session->'account'->>'role'; v_org:=(v_session->'organization'->>'id')::uuid;
 select coalesce(array_agg(value),'{}') into v_agendas from jsonb_array_elements_text(v_session->'agendaIds');
 select revision into v_revision from public.agenda_settings where organization_id=v_org;
 select max(t) into v_workflow from (
  select (select l.created_at from public.audit_logs l where v_role='general_manager' and l.organization_id=v_org order by l.created_at desc limit 1) t
  union all select (select l.created_at from public.audit_logs l where v_role='secretary' and l.organization_id=v_org and l.professional_id=any(v_agendas) order by l.created_at desc limit 1)
  union all select (select n.created_at from public.notifications n where n.user_id=v_id and n.organization_id=v_org order by n.created_at desc limit 1)
  union all select (select max(n.read_at) from public.notifications n where n.user_id=v_id and n.organization_id=v_org)
  union all select (select r.created_at from public.agenda_requests r where v_role='doctor' and r.organization_id=v_org and r.requested_by=v_id and r.professional_id=any(v_agendas) order by r.created_at desc limit 1)
 ) s;
 return jsonb_build_object('session',v_session,'revision',v_revision,'workflowRevision',v_workflow);
end;$function$
;

CREATE OR REPLACE FUNCTION public.agenda_time_list(p_value text)
 RETURNS time without time zone[]
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare item text; result time[]:='{}';
begin
 foreach item in array regexp_split_to_array(coalesce(p_value,''),',') loop
  item:=btrim(item);
  if item='' then continue; end if;
  if item !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then raise exception 'Horário inválido na regra: %',item; end if;
  result:=result||item::time;
 end loop;
 return result;
end;$function$
;

CREATE OR REPLACE FUNCTION public.anonymize_patient(p_actor bigint, p_org uuid, p_patient text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare paths jsonb; appts text[]; n_docs integer;
begin
 perform pg_advisory_xact_lock(194701,1);
 perform public.require_organization_manager(p_actor,p_org);
 if coalesce(char_length(btrim(p_reason)),0)<10 then raise exception 'Descreva o motivo do pedido (mínimo 10 caracteres)'; end if;
 perform 1 from public.patients where id=p_patient and organization_id=p_org for update;
 if not found then raise exception 'Paciente não encontrado'; end if;
 if exists(select 1 from public.attendances where patient_id=p_patient and organization_id=p_org) then
  raise exception 'Paciente com atendimento realizado: os dados precisam ser mantidos por obrigação legal (prontuário e fiscal). Use a exportação.';
 end if;
 if exists(select 1 from public.appointments where patient_id=p_patient and organization_id=p_org and cancelled_at is null and archived_at is null and date>=current_date) then
  raise exception 'Cancele os agendamentos futuros do paciente antes de anonimizar';
 end if;
 select coalesce(array_agg(id),'{}') into appts from public.appointments where patient_id=p_patient and organization_id=p_org;
 perform public.financial_operation(p_actor,'lgpd',p_patient);
 perform set_config('rn.anonymize','on',true);
 update public.patients set name='Paciente anonimizado',cpf=null,phone=null,email=null,card_number=null,address=null,address_zip=null,
  address_number=null,address_complement=null,address_neighborhood=null,address_city=null,address_state=null,
  newborn=false,guardian_name=null,archived_at=coalesce(archived_at,clock_timestamp()),archived_by=coalesce(archived_by,p_actor)
  where id=p_patient and organization_id=p_org;
 update public.appointments set notes=null,suggested_by_name=null,suggested_by_email=null,reschedule_reason=null,suggestion_reason=null,
  cancel_reason=case when cancel_reason is not null then '[removido por anonimização]' end
  where id=any(appts) and organization_id=p_org;
 -- Agendamentos que ficaram em aberto (passados, nem atendidos nem cancelados) saem da agenda junto
 -- com o paciente; sem isso ficavam órfãos e qualquer edição falhava com "Histórico sem permissão".
 update public.appointments set archived_at=clock_timestamp(),archived_by=p_actor
  where id=any(appts) and organization_id=p_org and cancelled_at is null and archived_at is null;
 update public.patient_history_events set text='[conteúdo removido por anonimização]' where patient_id=p_patient and organization_id=p_org;
 update public.appointment_reschedules set reason='[removido por anonimização]' where appointment_id=any(appts) and organization_id=p_org;
 update public.audit_logs set description='Registro de paciente anonimizado',
  metadata=case when jsonb_typeof(metadata)='object' then metadata
   ||case when metadata ? 'before' then jsonb_build_object('before',public.anonymized_appointment_json(metadata->'before')) else '{}'::jsonb end
   ||case when metadata ? 'after' then jsonb_build_object('after',public.anonymized_appointment_json(metadata->'after')) else '{}'::jsonb end
   else metadata end
  where organization_id=p_org and (patient_id=p_patient or appointment_id=any(appts));
 update public.agenda_requests set
  proposed_payload=public.anonymized_appointment_json(proposed_payload),
  previous_payload=public.anonymized_appointment_json(previous_payload)
  where organization_id=p_org and appointment_id=any(appts);
 -- Versões antigas usadas no merge também guardavam os dados pessoais.
 update public.agenda_row_versions set data=public.agenda_row_json('patients',p_patient,p_org)
  where organization_id=p_org and entity='patients' and row_id=p_patient;
 update public.agenda_row_versions set data=public.anonymized_appointment_json(data)
  where organization_id=p_org and entity='appointments' and row_id=any(appts);
 with gone as (delete from public.surgery_documents where patient_id=p_patient and organization_id=p_org returning object_path)
 select coalesce(jsonb_agg(object_path),'[]'::jsonb),count(*) into paths,n_docs from gone;
 update public.agenda_settings set revision=date_trunc('milliseconds',greatest(clock_timestamp(),revision+interval '1 millisecond')) where organization_id=p_org;
 perform set_config('rn.anonymize','',true);
 perform public.record_security_event(p_org,p_actor,'patient_anonymized',p_patient,jsonb_build_object('reason',left(btrim(p_reason),500),'appointments',coalesce(array_length(appts,1),0),'documents',n_docs),null);
 perform set_config('rn.operation','',true); perform set_config('rn.actor','',true); perform set_config('rn.organization','',true);
 return jsonb_build_object('objectPaths',paths,'appointments',coalesce(array_length(appts,1),0),'documents',n_docs);
end;$function$
;

CREATE OR REPLACE FUNCTION public.anonymized_appointment_json(p_data jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
 select case when p_data is null or jsonb_typeof(p_data)<>'object' then p_data else
  (p_data-'notes'-'suggestedByName'-'suggestedByEmail'-'rescheduleReason'-'suggestionReason'-'cancelReason'-'rescheduleHistory')
  ||case when p_data ? 'cancelReason' then jsonb_build_object('cancelReason','[removido por anonimização]') else '{}'::jsonb end
  ||case when jsonb_typeof(p_data->'rescheduleHistory')='array' then jsonb_build_object('rescheduleHistory',coalesce((select jsonb_agg(
      case when jsonb_typeof(e)='object' then e||'{"reason":"[removido por anonimização]"}'::jsonb else e end) from jsonb_array_elements(p_data->'rescheduleHistory') e),'[]'::jsonb))
    else '{}'::jsonb end
 end
$function$
;

CREATE OR REPLACE FUNCTION public.apply_agenda_changes(p_actor bigint, p_ops jsonb, p_audit jsonb DEFAULT '[]'::jsonb, p_request_id text DEFAULT NULL::text, p_decision text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_notification jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 org uuid; new_revision timestamptz; op jsonb; d jsonb; kind text; expected integer; rid text;
 request_status text; touched jsonb:='[]'::jsonb; t jsonb; existing integer; rs jsonb; pos integer;
begin
 perform pg_advisory_xact_lock(194701,1);
 org:=public.require_rn_agenda_actor_organization(p_actor);
 if p_request_id is not null then
  select status into request_status from public.agenda_requests where id=p_request_id for update;
  if request_status is distinct from 'pending' then
   return jsonb_build_object('ok',false,'conflict','request');
  end if;
  if p_decision not in ('accepted','denied') then raise exception 'Invalid decision'; end if;
 end if;
 perform public.financial_operation(p_actor,'agenda',p_request_id);
 update public.agenda_settings set revision=date_trunc('milliseconds',greatest(clock_timestamp(),revision+interval '1 millisecond')),updated_by=p_actor
  where organization_id=org returning revision into new_revision;

 for op in select value from jsonb_array_elements(coalesce(p_ops,'[]'::jsonb)) loop
  kind:=op->>'op'; d:=coalesce(op->'data','{}'::jsonb); rid:=coalesce(d->>'id',op->>'id');
  expected:=nullif(op->>'expectedVersion','')::integer;
  if kind in ('upsert_patient','archive_patient') then
   if kind='archive_patient' then
    update public.patients set archived_at=clock_timestamp(),archived_by=p_actor where id=rid and organization_id=org and row_version=expected and archived_at is null;
   elsif expected is null then
    insert into public.patients(id,organization_id,owner_professional_id,name,cpf,phone,email,insurance,card_number,address,address_zip,
      address_number,address_complement,address_neighborhood,address_city,address_state,newborn,guardian_name,created_by)
    values(rid,org,d->>'doctorId',btrim(d->>'name'),nullif(d->>'cpf',''),d->>'phone',d->>'email',d->>'insurance',d->>'cardNumber',d->>'address',
      d->>'addressZip',d->>'addressNumber',d->>'addressComplement',d->>'addressNeighborhood',d->>'addressCity',d->>'addressState',
      coalesce((d->>'newborn')::boolean,false),d->>'guardianName',p_actor)
    on conflict (id) do nothing;
   else
    update public.patients set owner_professional_id=d->>'doctorId',name=btrim(d->>'name'),cpf=nullif(d->>'cpf',''),phone=d->>'phone',email=d->>'email',
      insurance=d->>'insurance',card_number=d->>'cardNumber',address=d->>'address',address_zip=d->>'addressZip',address_number=d->>'addressNumber',
      address_complement=d->>'addressComplement',address_neighborhood=d->>'addressNeighborhood',address_city=d->>'addressCity',
      address_state=d->>'addressState',newborn=coalesce((d->>'newborn')::boolean,false),guardian_name=d->>'guardianName'
    where id=rid and organization_id=org and row_version=expected;
   end if;
   if not found then raise exception using errcode='P0001',message='Conflito de edição: paciente alterado por outra pessoa.'; end if;
   touched:=touched||jsonb_build_array(jsonb_build_object('entity','patients','id',rid));
  elsif kind in ('upsert_appointment','archive_appointment') then
   if kind='archive_appointment' then
    update public.appointments set archived_at=clock_timestamp(),archived_by=p_actor where id=rid and organization_id=org and row_version=expected and archived_at is null;
    if not found then raise exception using errcode='P0001',message='Conflito de edição: agendamento alterado por outra pessoa.'; end if;
   else
    if expected is null then
     insert into public.appointments(id,organization_id,professional_id,anesthetist_id,patient_id,hospital_id,date,time,duration_min,status,care_type,
       procedure,insurance,billing_method,guide_expiry,procedure_value,opme,reports,exams,notes,status_updated_at,reschedule_reason,suggestion_reason,
       suggested_by_name,suggested_by_email,cancelled_at,cancel_reason,created_by)
     values(rid,org,nullif(d->>'doctorId',''),nullif(d->>'anesthetistId',''),nullif(d->>'patientId',''),nullif(d->>'hospitalId',''),
       (d->>'date')::date,(d->>'time')::time,(d->>'duration')::integer,d->>'status',coalesce(nullif(d->>'careType',''),'outpatient'),
       coalesce(nullif(d->>'procedure',''),'Procedimento'),d->>'insurance',nullif(d->>'forma_cobranca',''),d->>'guideExpiry',nullif(d->>'procedureValue','')::numeric(12,2),
       coalesce((d->>'opme')::boolean,false),coalesce((d->>'reports')::boolean,false),coalesce((d->>'exams')::boolean,false),d->>'notes',
       nullif(d->>'statusUpdatedAt','')::timestamptz,d->>'rescheduleReason',d->>'suggestionReason',d->>'suggestedByName',d->>'suggestedByEmail',
       case when (op->>'cancelled')::boolean then coalesce(nullif(d->>'cancelledAt','')::timestamptz,clock_timestamp()) end,
       case when (op->>'cancelled')::boolean then coalesce(nullif(btrim(d->>'cancelReason'),''),'Não informado') end,p_actor)
     on conflict (id) do nothing;
    else
     update public.appointments set professional_id=nullif(d->>'doctorId',''),anesthetist_id=nullif(d->>'anesthetistId',''),
       patient_id=nullif(d->>'patientId',''),hospital_id=nullif(d->>'hospitalId',''),date=(d->>'date')::date,time=(d->>'time')::time,
       duration_min=(d->>'duration')::integer,status=d->>'status',care_type=coalesce(nullif(d->>'careType',''),'outpatient'),
       procedure=coalesce(nullif(d->>'procedure',''),'Procedimento'),insurance=d->>'insurance',billing_method=nullif(d->>'forma_cobranca',''),
       guide_expiry=d->>'guideExpiry',procedure_value=nullif(d->>'procedureValue','')::numeric(12,2),opme=coalesce((d->>'opme')::boolean,false),reports=coalesce((d->>'reports')::boolean,false),
       exams=coalesce((d->>'exams')::boolean,false),notes=d->>'notes',status_updated_at=nullif(d->>'statusUpdatedAt','')::timestamptz,
       reschedule_reason=d->>'rescheduleReason',suggestion_reason=d->>'suggestionReason',suggested_by_name=d->>'suggestedByName',
       suggested_by_email=d->>'suggestedByEmail',
       cancelled_at=case when (op->>'cancelled')::boolean then coalesce(cancelled_at,nullif(d->>'cancelledAt','')::timestamptz,clock_timestamp()) end,
       cancel_reason=case when (op->>'cancelled')::boolean then coalesce(nullif(btrim(d->>'cancelReason'),''),'Não informado') end,
       cancelled_by=case when (op->>'cancelled')::boolean then cancelled_by end
     where id=rid and organization_id=org and row_version=expected;
    end if;
    if not found then raise exception using errcode='P0001',message='Conflito de edição: agendamento alterado por outra pessoa.'; end if;
    -- Remarcações são append-only: só entradas além das já gravadas.
    select count(*) into existing from public.appointment_reschedules where appointment_id=rid;
    pos:=0;
    for rs in select value from jsonb_array_elements(case when jsonb_typeof(d->'rescheduleHistory')='array' then d->'rescheduleHistory' else '[]'::jsonb end) loop
     if pos>=existing then
      insert into public.appointment_reschedules(id,organization_id,appointment_id,position,from_date,from_time,to_date,to_time,reason,proposed_by,proposed_at)
      values(gen_random_uuid()::text,org,rid,pos,rs->>'fromDate',rs->>'fromTime',rs->>'toDate',rs->>'toTime',rs->>'reason',rs->>'proposedBy',rs->>'createdAt');
     end if;
     pos:=pos+1;
    end loop;
   end if;
   touched:=touched||jsonb_build_array(jsonb_build_object('entity','appointments','id',rid));
  elsif kind='append_history' then
   insert into public.patient_history_events(id,organization_id,patient_id,appointment_id,type,text,at,actor_user_id,created_by)
   values(rid,org,d->>'patientId',nullif(d->>'appointmentId',''),d->>'type',coalesce(d->>'text',''),
     coalesce(nullif(d->>'at','')::timestamptz,clock_timestamp()),p_actor,p_actor)
   on conflict (id) do nothing;
  elsif kind in ('upsert_block','delete_block') then
   if kind='delete_block' then
    delete from public.schedule_blocks where id=rid and organization_id=org and row_version=expected;
   elsif expected is null then
    insert into public.schedule_blocks(id,organization_id,professional_id,date,start_time,end_time,reason,created_by)
    values(rid,org,d->>'professionalId',(d->>'date')::date,(d->>'start')::time,(d->>'end')::time,btrim(d->>'reason'),p_actor)
    on conflict (id) do nothing;
   else
    update public.schedule_blocks set professional_id=d->>'professionalId',date=(d->>'date')::date,start_time=(d->>'start')::time,
      end_time=(d->>'end')::time,reason=btrim(d->>'reason')
    where id=rid and organization_id=org and row_version=expected;
   end if;
   if not found then raise exception using errcode='P0001',message='Conflito de edição: bloqueio alterado por outra pessoa.'; end if;
   touched:=touched||jsonb_build_array(jsonb_build_object('entity','scheduleBlocks','id',rid));
  elsif kind in ('upsert_rule','delete_rule') then
   if kind='delete_rule' then
    delete from public.scheduling_rules where id=rid and organization_id=org and row_version=expected;
   elsif expected is null then
    insert into public.scheduling_rules(id,organization_id,professional_id,hospital_id,name,severity,weekday,occurrence,start_time,end_time,
      max_patients,procedure_contains,preferred_times,forbidden_times,block_all_day,enabled,created_by)
    values(rid,org,d->>'professionalId',nullif(d->>'hospitalId',''),coalesce(d->>'name',''),coalesce(nullif(d->>'severity',''),'preference'),
      nullif(d->>'weekday','')::smallint,nullif(d->>'occurrence',''),nullif(d->>'start','')::time,nullif(d->>'end','')::time,
      nullif(d->>'maxPatients','')::integer,coalesce(d->>'procedureContains',''),public.agenda_time_list(d->>'preferredTimes'),
      public.agenda_time_list(d->>'forbiddenTimes'),coalesce((d->>'blockAllDay')::boolean,false),coalesce((d->>'enabled')::boolean,true),p_actor)
    on conflict (id) do nothing;
   else
    update public.scheduling_rules set professional_id=d->>'professionalId',hospital_id=nullif(d->>'hospitalId',''),name=coalesce(d->>'name',''),
      severity=coalesce(nullif(d->>'severity',''),'preference'),weekday=nullif(d->>'weekday','')::smallint,occurrence=nullif(d->>'occurrence',''),
      start_time=nullif(d->>'start','')::time,end_time=nullif(d->>'end','')::time,max_patients=nullif(d->>'maxPatients','')::integer,
      procedure_contains=coalesce(d->>'procedureContains',''),preferred_times=public.agenda_time_list(d->>'preferredTimes'),
      forbidden_times=public.agenda_time_list(d->>'forbiddenTimes'),block_all_day=coalesce((d->>'blockAllDay')::boolean,false),
      enabled=coalesce((d->>'enabled')::boolean,true)
    where id=rid and organization_id=org and row_version=expected;
   end if;
   if not found then raise exception using errcode='P0001',message='Conflito de edição: regra alterada por outra pessoa.'; end if;
   touched:=touched||jsonb_build_array(jsonb_build_object('entity','schedulingRules','id',rid));
  elsif kind in ('upsert_hospital','archive_hospital') then
   if kind='archive_hospital' then
    update public.hospitals set archived_at=clock_timestamp(),archived_by=p_actor where id=rid and organization_id=org and row_version=expected and archived_at is null;
   elsif expected is null then
    insert into public.hospitals(id,organization_id,name,abbreviation,created_by)
    values(rid,org,btrim(d->>'name'),nullif(btrim(coalesce(d->>'abbreviation','')),''),p_actor) on conflict (id) do nothing;
   else
    update public.hospitals set name=btrim(d->>'name'),abbreviation=nullif(btrim(coalesce(d->>'abbreviation','')),'')
    where id=rid and organization_id=org and row_version=expected;
   end if;
   if not found then raise exception using errcode='P0001',message='Conflito de edição: hospital alterado por outra pessoa.'; end if;
   touched:=touched||jsonb_build_array(jsonb_build_object('entity','hospitals','id',rid));
  elsif kind='save_settings' then
   update public.agenda_settings set work_start=(d->>'workStart')::time,work_end=(d->>'workEnd')::time,updated_by=p_actor where organization_id=org;
  else
   raise exception 'Operação de agenda inválida';
  end if;
 end loop;

 for t in select distinct value from jsonb_array_elements(touched) loop
  perform public.record_agenda_row_version(org,t->>'entity',t->>'id',new_revision);
 end loop;
 if p_request_id is not null then
  update public.agenda_requests set status=p_decision,decided_by=p_actor,decision_note=p_note,decided_at=new_revision where id=p_request_id;
 end if;
 insert into public.audit_logs(id,actor_user_id,actor_name,actor_role,action,professional_id,appointment_id,patient_id,description,metadata,created_at)
  select x.id,x.actor_user_id,x.actor_name,x.actor_role,x.action,x.professional_id,x.appointment_id,x.patient_id,x.description,x.metadata,coalesce(x.created_at,new_revision)
  from jsonb_to_recordset(coalesce(p_audit,'[]'::jsonb)) as x(id text,actor_user_id bigint,actor_name text,actor_role text,action text,professional_id text,
   appointment_id text,patient_id text,description text,metadata jsonb,created_at timestamptz);
 if p_notification is not null then
  insert into public.notifications(id,user_id,type,request_id,message,created_at)
  values(p_notification->>'id',(p_notification->>'user_id')::bigint,p_notification->>'type',p_request_id,p_notification->>'message',new_revision);
 end if;
 perform set_config('rn.operation','',true); perform set_config('rn.actor','',true);
 return jsonb_build_object('ok',true,'revision',public.agenda_iso(new_revision));
end;$function$
;

CREATE OR REPLACE FUNCTION public.apply_agenda_changes(p_actor bigint, p_ops jsonb, p_audit jsonb, p_request_id text, p_decision text, p_note text, p_notification jsonb, p_org uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ begin perform public.use_organization(p_actor,p_org); return public.apply_agenda_changes(p_actor,p_ops,p_audit,p_request_id,p_decision,p_note,p_notification); end;$function$
;

CREATE OR REPLACE FUNCTION public.appointment_billing_method(a jsonb, legacy text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
 select coalesce(nullif(a->>'forma_cobranca',''),nullif(a->>'billing_method',''),nullif(a->>'billingMethod',''),legacy);
$function$
;

CREATE OR REPLACE FUNCTION public.attribute_financial_attendance(p_id text, p_entity uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ begin perform public.billing_paused(); return null; end;$function$
;

CREATE OR REPLACE FUNCTION public.authorized_financial_attachment_actor(actor bigint, invoice uuid, record uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$ begin return false; end;$function$
;

CREATE OR REPLACE FUNCTION public.begin_financial_attachment(p_actor bigint, p_invoice uuid, p_record uuid, p_filename text, p_mime text, p_size bigint, p_replaces uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, storage_path text)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 attachment_id uuid:=gen_random_uuid();
 current_attachment public.financial_attachments%rowtype;
 v_org uuid;
begin
 v_org:=public.require_rn_agenda_actor_organization(p_actor);
 if (p_invoice is null)=(p_record is null) then
  raise exception 'Informe exatamente um pagamento';
 end if;
 if not public.authorized_financial_attachment_actor(p_actor,p_invoice,p_record) then
  raise exception 'Acesso negado';
 end if;
 if p_invoice is not null and not exists(
  select 1 from public.invoices i
  where i.id=p_invoice and i.organization_id=v_org and i.recipient_type='CONVENIO' and i.status='ACTIVE'
   and i.voided_at is null and i.paid_at is not null
 ) then
  raise exception 'NF paga não encontrada';
 end if;
 if p_record is not null and not exists(
  select 1 from public.billing_records b
  where b.id=p_record and b.organization_id=v_org and b.payment_status='PAGO' and b.paid_at is not null
   and b.received_amount is not null
   and (b.billing_method='PARTICULAR' or b.settlement_mode='DIRECT')
 ) then
  raise exception 'Pagamento direto não encontrado';
 end if;
 if p_filename is null or p_filename<>trim(p_filename)
   or p_filename~'[\\/[:cntrl:]]' or length(p_filename)>200
   or p_mime not in ('application/pdf','image/jpeg','image/png')
   or p_size<=0 or p_size>10485760 then
  raise exception 'Comprovante inválido';
 end if;
 if p_replaces is not null then
  select fa.* into current_attachment
  from public.financial_attachments fa
  where fa.id=p_replaces and fa.organization_id=v_org
  for update;
  if current_attachment.id is null or not current_attachment.is_current
    or current_attachment.status<>'READY'
    or current_attachment.invoice_id is distinct from p_invoice
    or current_attachment.billing_record_id is distinct from p_record then
   raise exception 'Comprovante atual não encontrado';
  end if;
 end if;
 perform public.financial_operation(p_actor,'payment_proof',coalesce(p_invoice,p_record)::text);
 insert into public.financial_attachments(
  id,document_type,invoice_id,billing_record_id,storage_path,
  original_filename,mime_type,file_size,replaces_attachment_id
 ) values(
  attachment_id,'PAYMENT_PROOF',p_invoice,p_record,
  format('org/%s/payment-proofs/%s/%s',v_org,coalesce(p_invoice,p_record),attachment_id),
  p_filename,p_mime,p_size,p_replaces
 );
 return query
  select attachment_id,format('org/%s/payment-proofs/%s/%s',v_org,coalesce(p_invoice,p_record),attachment_id);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.billing_entity_receipts_analytics(p_entity uuid)
 RETURNS TABLE(payment_year integer, payment_month integer, source text, amount numeric, operations bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
 with direct_payments as (
  select extract(year from b.paid_at)::integer payment_year,
         extract(month from b.paid_at)::integer payment_month,
         case when nullif(trim(b.invoice_number),'') is not null
           or exists (
            select 1 from public.invoice_billing_records item
            join public.invoices inv on inv.id=item.invoice_id
            where item.billing_record_id=b.id
             and item.is_active and inv.status='ACTIVE'
             and inv.voided_at is null and inv.recipient_type='PARTICULAR'
           )
           then 'Particular - Com NF' else 'Particular - Sem NF' end as source,
         b.received_amount::numeric amount
  from public.billing_records b
  where b.billing_entity_id=p_entity
   and b.settlement_mode='DIRECT'
   and b.billing_method='PARTICULAR'
   and b.payment_status='PAGO'
   and b.paid_at is not null
   and b.received_amount is not null
   and b.received_amount>=0
 ), insurance_payments as (
  select extract(year from i.paid_at)::integer payment_year,
         extract(month from i.paid_at)::integer payment_month,
         coalesce(nullif(upper(trim(i.payer)),''),'CONVÊNIO NÃO INFORMADO') as source,
         i.net_amount::numeric as amount
  from public.invoices i
  where i.billing_entity_id=p_entity
   and i.recipient_type='CONVENIO'
   and i.status='ACTIVE' and i.voided_at is null
   and i.paid_at is not null and i.net_amount is not null
   and i.net_amount>=0
 ), receipts as (
  select * from direct_payments
  union all
  select * from insurance_payments
 )
 select r.payment_year,r.payment_month,r.source,
        round(sum(r.amount),2) as amount,
        count(*)::bigint as operations
 from receipts r
 group by r.payment_year,r.payment_month,r.source
 order by r.payment_year,r.payment_month,r.source;
$function$
;

