CREATE OR REPLACE FUNCTION public.cancel_invite(p_actor bigint, p_org uuid, p_invite uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 perform public.require_organization_manager(p_actor,p_org);
 update public.auth_tokens set used_at=now()
  where id=p_invite and kind='invite' and organization_id=p_org and used_at is null;
 if not found then raise exception 'Convite não encontrado ou já utilizado'; end if;
 perform set_config('rn.organization','',true);
 return true;
end;$function$
;

CREATE OR REPLACE FUNCTION public.cancel_manual_attendance(p_actor bigint, p_data jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare a public.attendances%rowtype;
begin
 perform pg_advisory_xact_lock(194701,1);perform pg_advisory_xact_lock(194701,2);
 if not exists(select 1 from public.users where id=p_actor and role='general_manager') then raise exception 'Acesso restrito à gerência';end if;
 select * into a from public.attendances where id=p_data->>'id' for update;
 if a.id is null or a.origin not in ('FATURAMENTO_MANUAL','FISCAL_MANUAL') then raise exception 'Cancele atendimentos da Agenda na própria Agenda';end if;
 if a.status='cancelled' then return a.id;end if;
 if a.updated_at is distinct from (p_data->>'updated_at')::timestamptz then raise exception 'Atendimento alterado. Atualize';end if;
 if nullif(trim(p_data->>'reason'),'') is null then raise exception 'Informe o motivo do cancelamento';end if;
 if exists(select 1 from public.invoice_billing_records x join public.billing_records b on b.id=x.billing_record_id where b.attendance_id=a.id and x.is_active) then raise exception 'Remova ou regularize a Nota Fiscal vinculada antes de cancelar este atendimento.';end if;
 perform public.financial_operation(p_actor,'cancel_attendance',a.id);
 update public.invoice_requests set status='CANCELLED' where attendance_id=a.id and status='PENDING';
 update public.billing_records set payment_status='PENDENTE',received_amount=null,paid_at=null where attendance_id=a.id;
 update public.attendances set status='cancelled',cancelled_at=clock_timestamp(),cancelled_by=p_actor,cancellation_reason=trim(p_data->>'reason') where id=a.id;
 perform set_config('rn.operation','',true);perform set_config('rn.actor','',true);return a.id;
end;$function$
;

CREATE OR REPLACE FUNCTION public.check_fiscal_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if exists(select 1 from public.invoice_billing_records x join public.invoices i on i.id=x.invoice_id where x.is_active is distinct from (i.status='ACTIVE' and i.voided_at is null)) then raise exception 'Vínculo operacional incompatível com status fiscal';end if;
 if exists(select 1 from public.invoices i where i.recipient_type='PARTICULAR' and ((select count(*) from public.invoice_billing_records x where x.invoice_id=i.id)<>1 or (i.status='ACTIVE' and i.voided_at is null and not exists(select 1 from public.invoice_requests r join public.invoice_billing_records x on x.billing_record_id=r.billing_record_id and x.invoice_id=i.id where r.invoice_id=i.id and r.status='ISSUED' and i.billing_entity_id=r.billing_entity_id and i.recipient_tax_id=r.taker_tax_id and i.recipient_name=r.taker_name and i.recipient_address is not distinct from r.taker_address and i.patient_id=r.patient_id and i.recipient_kind=r.taker_kind)))) then raise exception 'NF Particular exige exatamente um atendimento e sua solicitação emitida';end if;
 if exists(select 1 from public.invoice_requests r join public.billing_records b on b.id=r.billing_record_id where r.status in ('PENDING','ISSUED') and (b.attendance_id<>r.attendance_id or b.billing_method<>'PARTICULAR' or b.payment_status<>'PAGO' or b.received_amount is distinct from r.received_amount_snapshot or b.paid_at is distinct from r.paid_at_snapshot or b.billing_entity_id<>r.billing_entity_id)) then raise exception 'Pagamento e solicitação fiscal incompatíveis';end if;
 if exists(select 1 from public.invoice_requests r left join public.invoices i on i.id=r.invoice_id where r.status='ISSUED' and (i.id is null or i.status<>'ACTIVE' or i.voided_at is not null)) then raise exception 'Solicitação emitida exige NF ativa';end if;
 if exists(select 1 from public.invoice_requests r join public.invoice_billing_records x on x.billing_record_id=r.billing_record_id and x.is_active where r.status='PENDING') then raise exception 'Solicitação pendente já possui NF ativa';end if;
 if exists(select 1 from public.invoice_billing_records x join public.invoices i on i.id=x.invoice_id join public.billing_records b on b.id=x.billing_record_id join public.attendances a on a.id=b.attendance_id where x.is_active and (i.recipient_type<>b.billing_method or a.status='cancelled')) then raise exception 'NF incompatível com atendimento';end if;
 if exists(select 1 from public.invoices i where i.recipient_type='CONVENIO' and i.status='ACTIVE' and i.voided_at is null and i.allocation_verified and (i.net_amount is null or not exists(select 1 from public.invoice_billing_records x where x.invoice_id=i.id) or exists(select 1 from public.invoice_billing_records x where x.invoice_id=i.id and x.received_amount is null) or i.net_amount is distinct from (select sum(x.received_amount) from public.invoice_billing_records x where x.invoice_id=i.id)+i.closing_adjustment)) then raise exception 'A soma dos itens e ajuste deve ser igual ao valor líquido';end if;
 if exists(select 1 from public.billing_records b where b.billing_method='PARTICULAR' and b.payment_status='PAGO' and b.payment_composition_verified and b.received_amount is distinct from (select sum(p.amount) from public.payment_parts p where p.billing_record_id=b.id)) then raise exception 'As formas de pagamento devem somar o valor recebido';end if;
 if exists(select 1 from public.invoices i where i.recipient_type='CONVENIO' and i.status='ACTIVE' and i.voided_at is null and i.paid_at is not null and i.payment_composition_verified and i.net_amount is distinct from (select sum(p.amount) from public.payment_parts p where p.invoice_id=i.id)) then raise exception 'As formas de pagamento devem somar o valor líquido';end if;
 if exists(select 1 from public.payment_parts p left join public.billing_records b on b.id=p.billing_record_id left join public.invoices i on i.id=p.invoice_id where (p.billing_record_id is not null and b.billing_method<>'PARTICULAR') or (p.invoice_id is not null and i.recipient_type<>'CONVENIO')) then raise exception 'Origem inválida da composição de pagamento';end if;
 if exists(select 1 from public.billing_records b where b.billing_method='CONVENIO' and b.settlement_mode='INVOICE' and (b.payment_status='PAGO') is distinct from exists(select 1 from public.invoice_billing_records x join public.invoices i on i.id=x.invoice_id where x.billing_record_id=b.id and x.is_active and i.paid_at is not null)) then raise exception 'Quitação de convênio exige NF ativa paga';end if;
 if exists(select 1 from public.attendances a join public.invoice_requests r on r.attendance_id=a.id where a.status='cancelled' and r.status in ('PENDING','ISSUED') and a.origin<>'AGENDA') then raise exception 'Atendimento manual cancelado com solicitação ativa';end if;
 if exists(select 1 from public.invoices where (status='REPLACED') is distinct from (replaced_by_invoice_id is not null)) then raise exception 'Substituição exige documento sucessor';end if;
 if exists(with recursive chain as(select id,replaced_by_invoice_id,array[id] path,false cycle from public.invoices where replaced_by_invoice_id is not null union all select c.id,i.replaced_by_invoice_id,c.path||i.id,i.id=any(c.path) from chain c join public.invoices i on i.id=c.replaced_by_invoice_id where not c.cycle) select 1 from chain where cycle) then raise exception 'Ciclo de substituição fiscal';end if;
 return null;
end;$function$
;

CREATE OR REPLACE FUNCTION public.close_billing_month(p_actor bigint, p_entity uuid, p_month text, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 rn_org_id uuid;
 first_day date;
 snapshot_data jsonb;
 saved_id uuid;
 latest public.billing_monthly_closing_events%rowtype;
begin
 rn_org_id:=public.require_rn_agenda_actor_organization(p_actor);
 if not exists(select 1 from public.billing_entities where id=p_entity and organization_id=rn_org_id) then raise exception 'Entidade recebedora não encontrada na organização';end if;
 if not exists(select 1 from public.users where id=p_actor and role='general_manager' and active) then
  raise exception 'Somente a gerência pode fechar uma competência';
 end if;
 if p_month is null or p_month !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' then
  raise exception 'Competência inválida';
 end if;
 first_day:=(p_month||'-01')::date;
 if first_day>=date_trunc('month',timezone('America/Sao_Paulo',now()))::date then
  raise exception 'A competência atual ou futura não pode ser encerrada';
 end if;
 if length(coalesce(p_notes,''))>2000 then raise exception 'Observação muito longa';end if;

 perform pg_advisory_xact_lock(hashtext(p_entity::text||p_month)::bigint);
 select * into latest from public.billing_monthly_closing_events
  where billing_entity_id=p_entity and organization_id=rn_org_id and competence_month=first_day
  order by event_number desc limit 1;
 if latest.id is not null then
  if latest.event_type<>'UNLOCKED' then raise exception 'Competência bloqueada. Desbloqueie com a senha do Gerente Geral';end if;
 elsif exists(select 1 from public.billing_monthly_closings
   where billing_entity_id=p_entity and organization_id=rn_org_id and competence_month=first_day) then
  raise exception 'Competência bloqueada. Desbloqueie com a senha do Gerente Geral';
 end if;

 snapshot_data:=public.preview_billing_month(p_actor,p_entity,p_month);
 if coalesce((snapshot_data->'cash'->>'insurance_paid_invoices_without_net')::integer,0)>0
    or coalesce((snapshot_data->'issued_invoices'->>'without_net_amount')::integer,0)>0 then
   raise exception 'Existem NFs sem valor líquido identificado. Revise antes de fechar';
 end if;
 if latest.id is not null then
  insert into public.billing_monthly_closing_events(
    billing_entity_id,competence_month,event_type,snapshot,snapshot_checksum,notes,actor_id)
  values(p_entity,first_day,'CLOSED',snapshot_data,md5(snapshot_data::text),
    nullif(trim(p_notes),''),p_actor) returning id into saved_id;
 else
  insert into public.billing_monthly_closings(
    billing_entity_id,competence_month,snapshot,snapshot_checksum,notes,closed_by)
  values(p_entity,first_day,snapshot_data,md5(snapshot_data::text),
     nullif(trim(p_notes),''),p_actor) returning id into saved_id;
 end if;
 return saved_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.commit_agenda_change(p_expected timestamp with time zone, p_payload jsonb, p_revision timestamp with time zone, p_audit jsonb, p_request_id text DEFAULT NULL::text, p_decision text DEFAULT NULL::text, p_actor bigint DEFAULT NULL::bigint, p_note text DEFAULT NULL::text, p_notification jsonb DEFAULT NULL::jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 raise exception using errcode='P0001',message='Agenda migrada; atualize a página.';
end;$function$
;

CREATE OR REPLACE FUNCTION public.complete_financial_attachment(p_actor bigint, p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare attachment public.financial_attachments%rowtype;
begin
 select * into attachment from public.financial_attachments where id=p_id for update;
 if attachment.id is null or attachment.status<>'PENDING' or attachment.created_by<>p_actor then raise exception 'Envio não disponível';end if;
 if not public.authorized_financial_attachment_actor(p_actor,attachment.invoice_id,attachment.billing_record_id) then raise exception 'Acesso negado';end if;
 if attachment.invoice_id is not null and not exists(select 1 from public.invoices where id=attachment.invoice_id and status='ACTIVE' and voided_at is null and paid_at is not null) then raise exception 'Pagamento não está mais ativo';end if;
 if attachment.billing_record_id is not null and not exists(select 1 from public.billing_records where id=attachment.billing_record_id and payment_status='PAGO' and paid_at is not null) then raise exception 'Pagamento não está mais ativo';end if;
 perform public.financial_operation(p_actor,'payment_proof',coalesce(attachment.invoice_id,attachment.billing_record_id)::text);
 if attachment.replaces_attachment_id is not null then update public.financial_attachments set is_current=false,deactivated_at=clock_timestamp(),deactivation_reason='REPLACED',replaced_by_attachment_id=attachment.id where id=attachment.replaces_attachment_id and is_current;end if;
 update public.financial_attachments set status='READY',is_current=true where id=attachment.id;
end;$function$
;

CREATE OR REPLACE FUNCTION public.confirm_email(p_token_hash text)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare t public.auth_tokens%rowtype;
begin
 select * into t from public.auth_tokens where token_hash=p_token_hash and kind='verify_email' for update;
 if not found or t.used_at is not null or t.expires_at<=now() then raise exception 'Link inválido ou expirado'; end if;
 update public.auth_tokens set used_at=now() where id=t.id;
 update public.users set email_verified_at=coalesce(email_verified_at,now()) where id=t.user_id and lower(email)=lower(t.email);
 return t.user_id;
end;$function$
;

CREATE OR REPLACE FUNCTION public.consume_security_limit(p_key text, p_limit integer, p_seconds integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare n integer; t timestamptz := clock_timestamp();
begin
  if p_limit < 1 or p_limit > 10000 or p_seconds < 1 or p_seconds > 86400 then raise exception 'Invalid limit'; end if;
  delete from public.security_rate_limits where expires_at < t;
  insert into public.security_rate_limits(key,hits,expires_at) values(p_key,1,t + make_interval(secs=>p_seconds))
  on conflict(key) do update set hits=public.security_rate_limits.hits+1
  returning hits into n;
  return n <= p_limit;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.create_account_organization(p_actor bigint, p_org uuid, p_name text, p_kind text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare acc public.accounts%rowtype; new_id uuid:=gen_random_uuid(); base text; v_slug text;
begin
 perform pg_advisory_xact_lock(194701,7);
 perform public.use_organization(p_actor,p_org);
 select a.* into acc from public.accounts a join public.organizations o on o.account_id=a.id where o.id=p_org for update of a;
 if acc.owner_user_id is distinct from p_actor then raise exception 'Somente o titular da conta cria organizações'; end if;
 if (select role from public.users where id=p_actor)<>'general_manager' then raise exception 'Somente o titular da conta cria organizações'; end if;
 if coalesce(char_length(btrim(p_name)),0) not between 2 and 120 then raise exception 'Informe o nome da organização'; end if;
 if p_kind not in ('MANAGEMENT_COMPANY','CLINIC','SOLO_DOCTOR') then raise exception 'Tipo de organização inválido'; end if;
 if (select count(*) from public.organizations where account_id=acc.id and active)>=acc.max_organizations then raise exception 'Limite de organizações do plano atingido'; end if;
 base:=trim(both '-' from regexp_replace(lower(translate(btrim(p_name),'áàâãäéèêëíìîïóòôõöúùûüçñ','aaaaaeeeeiiiiooooouuuucn')),'[^a-z0-9]+','-','g'));
 v_slug:=left(coalesce(nullif(base,''),'organizacao'),48)||'-'||left(replace(new_id::text,'-',''),6);
 insert into public.organizations(id,slug,name,kind,active,account_id) values(new_id,v_slug,btrim(p_name),p_kind,true,acc.id);
 perform set_config('rn.organization','',true);
 insert into public.agenda_settings(organization_id) values(new_id);
 insert into public.organization_memberships(organization_id,user_id,role,active) values(new_id,p_actor,'general_manager',true);
 return new_id;
end;$function$
;

CREATE OR REPLACE FUNCTION public.create_invite(p_actor bigint, p_org uuid, p_email text, p_name text, p_role text, p_agenda_ids jsonb, p_doctor_id text, p_token_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_email text:=lower(btrim(p_email)); existing public.users%rowtype; grant_id text;
begin
 perform pg_advisory_xact_lock(194701,1);
 perform public.use_organization(p_actor,p_org);
 if not exists(select 1 from public.users u join public.organization_memberships m on m.user_id=u.id and m.organization_id=p_org and m.active and m.role='general_manager'
   where u.id=p_actor and u.role='general_manager' and u.active) then raise exception 'Acesso restrito à gerência'; end if;
 if v_email is null or v_email !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' or length(v_email)>254 then raise exception 'E-mail inválido'; end if;
 if p_role not in ('general_manager','secretary','doctor') then raise exception 'Papel inválido'; end if;
 if p_role='doctor' then
  if p_doctor_id is null or not exists(select 1 from public.doctors where id=p_doctor_id and organization_id=p_org) then raise exception 'Selecione um médico existente'; end if;
  if exists(select 1 from public.users where doctor_id=p_doctor_id) then raise exception 'Este médico já possui um acesso'; end if;
 elsif p_doctor_id is not null then raise exception 'Vínculo de médico só vale para o papel médico';
 end if;
 if p_agenda_ids is not null then
  if jsonb_typeof(p_agenda_ids)<>'array' then raise exception 'Agendas inválidas'; end if;
  for grant_id in select jsonb_array_elements_text(p_agenda_ids) loop
   if not exists(select 1 from public.doctors where id=grant_id and organization_id=p_org) then raise exception 'Agenda inexistente'; end if;
  end loop;
 end if;
 select * into existing from public.users where lower(email)=v_email;
 if found then
  if exists(select 1 from public.organization_memberships where user_id=existing.id and organization_id=p_org and active) then raise exception 'Essa pessoa já faz parte da organização'; end if;
  if existing.role<>p_role then raise exception 'Essa pessoa já tem conta com outro papel'; end if;
  if p_role='doctor' then raise exception 'Médico com conta existente ainda não pode ser convidado para outra organização'; end if;
 end if;
 update public.auth_tokens set used_at=now() where kind='invite' and organization_id=p_org and lower(email)=v_email and used_at is null;
 insert into public.auth_tokens(token_hash,kind,email,organization_id,role,payload,created_by,expires_at)
  values(p_token_hash,'invite',v_email,p_org,p_role,jsonb_build_object('name',nullif(btrim(coalesce(p_name,'')),''),'agendaIds',coalesce(p_agenda_ids,'[]'::jsonb),'doctorId',p_doctor_id),p_actor,now()+interval '7 days');
 return jsonb_build_object('existingUser',existing.id is not null,'organization',(select name from public.organizations where id=p_org));
end;$function$
;

CREATE OR REPLACE FUNCTION public.current_organization_id()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare a bigint:=nullif(current_setting('rn.actor',true),'')::bigint; o uuid:=nullif(current_setting('rn.organization',true),'')::uuid;
begin
 if a is not null then return public.actor_organization_id(a); end if;
 return o;
end;$function$
;

CREATE OR REPLACE FUNCTION public.deactivate_reversed_payment_proofs()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if tg_table_name='billing_records' and old.payment_status='PAGO' and new.payment_status='PENDENTE' then
  update public.financial_attachments set is_current=false,deactivated_at=clock_timestamp(),deactivation_reason='PAYMENT_REVERSED' where billing_record_id=new.id and status='READY' and is_current;
 elsif tg_table_name='invoices' and old.paid_at is not null and new.paid_at is null then
  update public.financial_attachments set is_current=false,deactivated_at=clock_timestamp(),deactivation_reason='PAYMENT_REVERSED' where invoice_id=new.id and status='READY' and is_current;
 end if;
 return new;
end;$function$
;

CREATE OR REPLACE FUNCTION public.deactivate_user_access(p_actor bigint, p_target bigint)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare org uuid; target_user public.users%rowtype; other_active boolean;
begin
 perform pg_advisory_xact_lock(194701,1);
 org:=public.actor_organization_id(p_actor);
 if not exists (
  select 1 from public.users actor
  join public.organization_memberships membership on membership.user_id=actor.id
  where actor.id=p_actor and actor.role='general_manager' and actor.active
    and membership.organization_id=org and membership.role='general_manager' and membership.active
 ) then raise exception 'Acesso restrito à gerência'; end if;
 if p_target is null or p_target=p_actor then raise exception 'O gerente não pode desativar seu próprio acesso'; end if;
 if exists(select 1 from public.organizations o join public.accounts a on a.id=o.account_id where o.id=org and a.owner_user_id=p_target) then
  raise exception 'O titular da conta não pode ser removido da organização';
 end if;
 select * into target_user from public.users where id=p_target for update;
 if not found then raise exception 'Usuário inexistente'; end if;
 if not exists(select 1 from public.organization_memberships where organization_id=org and user_id=p_target and active) then
  if exists(select 1 from public.organization_memberships where organization_id=org and user_id=p_target) then return false; end if;
  raise exception 'Conta fora da organização atual';
 end if;
 update public.organization_memberships set active=false,updated_at=clock_timestamp() where organization_id=org and user_id=p_target;
 select exists(select 1 from public.organization_memberships where user_id=p_target and active) into other_active;
 -- Sem nenhum outro vínculo ativo, a conta inteira é desativada.
 if not other_active then update public.users set active=false,updated_at=clock_timestamp() where id=p_target; end if;
 delete from public.sessions where user_id=p_target and (organization_id=org or not other_active or organization_id is null);
 insert into public.directory_audit(actor_id,kind,record_id,before_data,after_data,organization_id)
 values(p_actor,'user_access',p_target::text,
        jsonb_build_object('email',target_user.email,'role',target_user.role,'active',true),
        jsonb_build_object('email',target_user.email,'role',target_user.role,'active',other_active,'access_revoked',true,'organization_revoked',org),org);
 return true;
end;$function$
;

CREATE OR REPLACE FUNCTION public.deactivate_user_access(p_actor bigint, p_target bigint, p_org uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ begin perform public.use_organization(p_actor,p_org); return public.deactivate_user_access(p_actor,p_target); end;$function$
;

CREATE OR REPLACE FUNCTION public.derive_doctor_specialty()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ begin
 if tg_op='INSERT' or new.specialty is distinct from old.specialty then
  if not public.valid_medical_specialty(new.specialty) then raise exception 'Selecione uma especialidade da lista';end if;
 end if;
 new.category:=case when public.is_anesthesiologist(new.specialty) then 'anesthetist' else 'doctor' end;return new;
end;$function$
;

CREATE OR REPLACE FUNCTION public.export_patient_data(p_actor bigint, p_org uuid, p_patient text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare p public.patients%rowtype; result jsonb;
begin
 perform public.require_organization_manager(p_actor,p_org);
 select * into p from public.patients where id=p_patient and organization_id=p_org;
 if not found then raise exception 'Paciente não encontrado'; end if;
 result:=jsonb_build_object(
  'exportedAt',now(),
  'organization',(select name from public.organizations where id=p_org),
  'patient',to_jsonb(p)-'organization_id'-'row_version',
  'appointments',coalesce((select jsonb_agg((to_jsonb(a)-'organization_id'-'row_version')||jsonb_build_object(
     'professional',(select name from public.doctors where id=a.professional_id),
     'anesthetist',(select name from public.doctors where id=a.anesthetist_id),
     'hospital',(select name from public.hospitals where id=a.hospital_id and organization_id=p_org)) order by a.date,a.time)
   from public.appointments a where a.patient_id=p_patient and a.organization_id=p_org),'[]'::jsonb),
  'reschedules',coalesce((select jsonb_agg(to_jsonb(r)-'organization_id'-'row_version' order by r.appointment_id,r.position)
   from public.appointment_reschedules r join public.appointments a on a.id=r.appointment_id and a.organization_id=p_org
   where a.patient_id=p_patient and r.organization_id=p_org),'[]'::jsonb),
  'history',coalesce((select jsonb_agg(jsonb_build_object('type',h.type,'text',h.text,'at',h.at,'appointmentId',h.appointment_id) order by h.at)
   from public.patient_history_events h where h.patient_id=p_patient and h.organization_id=p_org),'[]'::jsonb),
  'documents',coalesce((select jsonb_agg(jsonb_build_object('name',d.name,'category',d.category,'size',d.size,'createdAt',d.created_at,'appointmentId',d.appointment_id) order by d.created_at)
   from public.surgery_documents d where d.patient_id=p_patient and d.organization_id=p_org and d.status='ready'),'[]'::jsonb));
 perform public.record_security_event(p_org,p_actor,'patient_export',p_patient,'{}'::jsonb,null);
 perform set_config('rn.organization','',true);
 return result;
end;$function$
;

CREATE OR REPLACE FUNCTION public.financial_attachment_log_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare op uuid:=nullif(current_setting('rn.operation',true),'')::uuid; actor public.users%rowtype; before_value jsonb; after_value jsonb; action_name text;
begin
 if op is null then raise exception 'Alteração financeira exige log';end if;
 select * into actor from public.users where id=nullif(current_setting('rn.actor',true),'')::bigint;
 if actor.id is null then raise exception 'Autor inválido';end if;
 if tg_op='INSERT' and new.status='PENDING' then return new;end if;
 if tg_op='UPDATE' and old.status='PENDING' and new.status='REJECTED' then return new;end if;
 before_value:=case when tg_op='INSERT' or (tg_op='UPDATE' and old.status='PENDING' and new.status='READY') then null else public.financial_attachment_snapshot(to_jsonb(old)) end;
 after_value:=case when tg_op='DELETE' then null else public.financial_attachment_snapshot(to_jsonb(new)) end;
 if tg_op='UPDATE' and before_value is not null and before_value=after_value then return new;end if;
 action_name:=case when before_value is null then 'INSERT' when after_value is null then 'DELETE' else 'UPDATE' end;
 insert into public.financial_logs(id,actor_id,actor_name,actor_email,kind,record_id)
 values(op,actor.id,coalesce(nullif(actor.name,''),actor.email,'Não informado'),actor.email,current_setting('rn.kind',true),nullif(current_setting('rn.record',true),'')) on conflict(id) do nothing;
 insert into public.financial_log_changes(log_id,record_type,record_id,action,before_data,after_data)
 values(op,'financial_attachments',coalesce(new.id,old.id)::text,action_name,before_value,after_value);
 return coalesce(new,old);
end;$function$
;

CREATE OR REPLACE FUNCTION public.financial_attachment_snapshot(value jsonb)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
 select case when value is null then null else jsonb_strip_nulls(jsonb_build_object(
  'document_type',value->'document_type','original_filename',value->'original_filename',
  'mime_type',value->'mime_type','file_size',value->'file_size','status',value->'status',
  'is_current',value->'is_current','deactivation_reason',value->'deactivation_reason',
  'invoice_id',value->'invoice_id','billing_record_id',value->'billing_record_id'
 )) end
$function$
;

