 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin raise exception using errcode='P0001',message='Agenda migrada; atualize a página.'; end;$function$
;

CREATE OR REPLACE FUNCTION public.get_billing_month_closing(p_actor bigint, p_entity uuid, p_month text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
 rn_org_id uuid;
 snap jsonb;
 original public.billing_monthly_closings%rowtype;
 latest public.billing_monthly_closing_events%rowtype;
 saved_snapshot jsonb;
 saved_id uuid;
 saved_at timestamptz;
 saved_by bigint;
 saved_notes text;
 saved_checksum text;
 is_closed boolean;
 revisions jsonb;
begin
 rn_org_id:=public.require_rn_agenda_actor_organization(p_actor);
 if not exists(select 1 from public.users where id=p_actor and active and role='general_manager') then raise exception 'Somente a gerência consulta o fechamento mensal';end if;
 if not exists(select 1 from public.billing_entities where id=p_entity and organization_id=rn_org_id) then raise exception 'Entidade recebedora não encontrada na organização';end if;
 snap:=public.preview_billing_month(p_actor,p_entity,p_month);
 select * into original from public.billing_monthly_closings
  where billing_entity_id=p_entity and organization_id=rn_org_id and competence_month=(p_month||'-01')::date;
 select * into latest from public.billing_monthly_closing_events
  where billing_entity_id=p_entity and organization_id=rn_org_id and competence_month=(p_month||'-01')::date
  order by event_number desc limit 1;
 is_closed:=case when latest.id is not null then latest.event_type='CLOSED'
                  else original.id is not null end;
 if latest.id is not null and latest.event_type='CLOSED' then
   saved_snapshot:=latest.snapshot;saved_id:=latest.id;
   saved_at:=latest.created_at;saved_by:=latest.actor_id;
   saved_notes:=latest.notes;saved_checksum:=latest.snapshot_checksum;
 elsif original.id is not null then
   saved_snapshot:=original.snapshot;saved_id:=original.id;
   saved_at:=original.closed_at;saved_by:=original.closed_by;
   saved_notes:=original.notes;saved_checksum:=original.snapshot_checksum;
 end if;

 select coalesce(jsonb_agg(to_jsonb(h) order by h.version),'[]'::jsonb) into revisions from (
   select 0::bigint version,o.id,o.closed_at date,o.closed_by actor_id,o.notes,
    'CLOSED'::text event_type
   from public.billing_monthly_closings o
   where o.billing_entity_id=p_entity and o.organization_id=rn_org_id and o.competence_month=(p_month||'-01')::date
   union all
   select e.event_number,e.id,e.created_at,e.actor_id,e.notes,e.event_type
   from public.billing_monthly_closing_events e
   where e.billing_entity_id=p_entity and e.organization_id=rn_org_id and e.competence_month=(p_month||'-01')::date
 ) h;
 return jsonb_build_object(
  'current',snap,'closed',is_closed,
  'unlocked',latest.id is not null and latest.event_type='UNLOCKED',
  'history',revisions,
  'closing',case when saved_snapshot is null then null else jsonb_build_object(
    'id',saved_id,'snapshot',saved_snapshot,'closed_at',saved_at,
    'closed_by',saved_by,'notes',saved_notes,
    'changed_since_close',md5(snap::text)<>saved_checksum) end
 );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.guard_agenda_appointment_availability()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  a jsonb; prior jsonb; b jsonb; r jsonb; p jsonb;
  old_payload jsonb; day_value date; occurrence integer; weekday integer;
  beginning integer; ending integer; block_start integer; block_end integer;
  work_start integer; work_end integer; r_start integer; r_end integer;
  pid text; doctor text; hospital_id text; procedure_name text; date_text text;
  allowed_times text[]; forbidden_time text; max_patients integer; used_count integer;
BEGIN
  PERFORM pg_advisory_xact_lock(194701,1);
  old_payload:=CASE WHEN TG_OP='UPDATE' THEN OLD.payload ELSE '{}'::jsonb END;
  FOR a IN SELECT value FROM jsonb_array_elements(coalesce(NEW.payload->'appointments','[]'::jsonb))
  LOOP
    IF a->>'status'='cancelled' THEN CONTINUE; END IF;
    SELECT value INTO prior FROM jsonb_array_elements(coalesce(old_payload->'appointments','[]'::jsonb))
      WHERE value->>'id'=a->>'id' LIMIT 1;
    IF prior IS NOT NULL AND
      (prior->>'date',prior->>'time',prior->>'duration',prior->>'doctorId',
       prior->>'anesthetistId',prior->>'hospitalId',prior->>'procedure')
      IS NOT DISTINCT FROM
      (a->>'date',a->>'time',a->>'duration',a->>'doctorId',
       a->>'anesthetistId',a->>'hospitalId',a->>'procedure') THEN
      CONTINUE;
    END IF;
    date_text:=a->>'date';
    IF date_text IS NULL OR a->>'time' IS NULL THEN CONTINUE; END IF;
    day_value:=date_text::date; weekday:=extract(dow from day_value)::int;
    occurrence:=((extract(day from day_value)::int-1)/7)+1;
    beginning:=split_part(a->>'time',':',1)::int*60+split_part(a->>'time',':',2)::int;
    ending:=beginning+coalesce((a->>'duration')::int,0);
    IF ending<=beginning THEN
      RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='Horário indisponível: duração inválida.';
    END IF;
    doctor:=a->>'doctorId';hospital_id:=a->>'hospitalId';procedure_name:=coalesce(a->>'procedure','');

    -- Manual schedule blocks apply to both surgeon and anesthetist, including
    -- intervals crossed by the appointment rather than just the start time.
    FOR b IN SELECT value FROM jsonb_array_elements(coalesce(NEW.payload->'scheduleBlocks','[]'::jsonb))
      WHERE value->>'date'=date_text AND value->>'professionalId' IN (doctor,coalesce(a->>'anesthetistId',''))
    LOOP
      block_start:=split_part(b->>'start',':',1)::int*60+split_part(b->>'start',':',2)::int;
      block_end:=split_part(b->>'end',':',1)::int*60+split_part(b->>'end',':',2)::int;
      IF beginning<block_end AND ending>block_start THEN
        RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='Horário indisponível: bloqueio do profissional.';
      END IF;
    END LOOP;
    IF doctor IS NULL OR doctor='' THEN CONTINUE; END IF;

    SELECT value INTO p FROM jsonb_array_elements(coalesce(NEW.payload->'professionals','[]'::jsonb))
      WHERE value->>'id'=doctor LIMIT 1;
    work_start:=coalesce(nullif(split_part(coalesce(p->'agendaSettings'->>'workStart',NEW.payload->'settings'->>'workStart','07:00'),':',1),''),'07')::int*60
      +coalesce(nullif(split_part(coalesce(p->'agendaSettings'->>'workStart',NEW.payload->'settings'->>'workStart','07:00'),':',2),''),'00')::int;
    work_end:=coalesce(nullif(split_part(coalesce(p->'agendaSettings'->>'workEnd',NEW.payload->'settings'->>'workEnd','19:00'),':',1),''),'19')::int*60
      +coalesce(nullif(split_part(coalesce(p->'agendaSettings'->>'workEnd',NEW.payload->'settings'->>'workEnd','19:00'),':',2),''),'00')::int;

    FOR r IN SELECT value FROM jsonb_array_elements(coalesce(NEW.payload->'schedulingRules','[]'::jsonb))
      WHERE value->>'professionalId'=doctor AND value->>'enabled' IS DISTINCT FROM 'false'
        AND (value->>'blockAllDay'='true' OR value->>'severity'='block')
    LOOP
      IF nullif(r->>'weekday','') IS NOT NULL AND (r->>'weekday')::int<>weekday THEN CONTINUE; END IF;
      IF nullif(r->>'occurrence','') IS NOT NULL THEN
        IF r->>'occurrence'='last' THEN
          IF extract(month from day_value+7)::int=extract(month from day_value)::int THEN CONTINUE; END IF;
        ELSIF (r->>'occurrence')::int<>occurrence THEN CONTINUE; END IF;
      END IF;
      IF r->>'blockAllDay'='true' THEN
        RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='Horário indisponível: dia totalmente bloqueado.';
      END IF;
      -- A rule's start/end encode the allowed window. Its complement is
      -- blocked, as already drawn by the existing desktop calendar.
      IF nullif(r->>'start','') IS NOT NULL THEN
        r_start:=split_part(r->>'start',':',1)::int*60+split_part(r->>'start',':',2)::int;
        IF r_start>work_start AND beginning<least(r_start,work_end) AND ending>work_start THEN
          RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='Horário indisponível: antes da janela permitida.';
        END IF;
      END IF;
      IF nullif(r->>'end','') IS NOT NULL THEN
        r_end:=split_part(r->>'end',':',1)::int*60+split_part(r->>'end',':',2)::int;
        IF r_end<work_end AND beginning<work_end AND ending>greatest(r_end,work_start) THEN
          RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='Horário indisponível: após a janela permitida.';
        END IF;
      END IF;
      FOR forbidden_time IN SELECT btrim(value) FROM regexp_split_to_table(coalesce(r->>'forbiddenTimes',''),',') AS value
        WHERE btrim(value)<>'' LOOP
        block_start:=split_part(forbidden_time,':',1)::int*60+split_part(forbidden_time,':',2)::int;
        IF beginning<least(block_start+30,work_end) AND ending>block_start THEN
          RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='Horário indisponível: horário proibido.';
        END IF;
      END LOOP;
      -- Advanced rule restrictions keep their existing scope (hospital /
      -- procedure), unlike absolute time bands and full-day closure.
      IF nullif(r->>'hospitalId','') IS NOT NULL AND r->>'hospitalId' IS DISTINCT FROM hospital_id THEN CONTINUE; END IF;
      IF nullif(r->>'procedureContains','') IS NOT NULL AND position(lower(r->>'procedureContains') in lower(procedure_name))=0 THEN CONTINUE; END IF;
      IF nullif(r->>'preferredTimes','') IS NOT NULL THEN
        SELECT array_agg(btrim(value)) INTO allowed_times FROM regexp_split_to_table(r->>'preferredTimes',',') AS value WHERE btrim(value)<>'';
        IF array_length(allowed_times,1)>0 AND NOT (a->>'time'=ANY(allowed_times)) THEN
          RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='Horário indisponível: fora dos horários permitidos.';
        END IF;
      END IF;
      IF nullif(r->>'maxPatients','') IS NOT NULL THEN
        max_patients:=(r->>'maxPatients')::int;
        IF max_patients>0 THEN
          SELECT count(*) INTO used_count FROM jsonb_array_elements(coalesce(NEW.payload->'appointments','[]'::jsonb)) AS item
          WHERE item->>'id' IS DISTINCT FROM a->>'id' AND item->>'doctorId'=doctor
            AND item->>'date'=date_text AND item->>'status' IS DISTINCT FROM 'cancelled'
            AND (nullif(r->>'hospitalId','') IS NULL OR item->>'hospitalId'=r->>'hospitalId');
          IF used_count>=max_patients THEN
            RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='Horário indisponível: limite diário atingido.';
          END IF;
        END IF;
      END IF;
    END LOOP;
  END LOOP;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.guard_agenda_row()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare ctx uuid:=public.current_organization_id();
        actor bigint:=nullif(current_setting('rn.actor',true),'')::bigint;
begin
 if tg_op='DELETE' then
  if ctx is not null and old.organization_id<>ctx then raise exception 'Registro fora da organização atual'; end if;
  if tg_table_name in ('schedule_blocks','scheduling_rules') then return old; end if;
  raise exception 'Exclusão direta bloqueada; use o arquivamento.';
 end if;
 if tg_op='INSERT' then
  new.organization_id:=coalesce(new.organization_id,ctx);
  if new.organization_id is null then raise exception 'Registro sem organização'; end if;
  if ctx is not null and new.organization_id<>ctx then raise exception 'Registro fora da organização atual'; end if;
  if coalesce(current_setting('rn.agenda_migration',true),'')<>'on'
    and new.id !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
   raise exception 'Identificador inválido';
  end if;
  new.created_at:=clock_timestamp(); new.created_by:=coalesce(new.created_by,actor);
  new.updated_at:=new.created_at; new.updated_by:=coalesce(new.updated_by,new.created_by);
  new.row_version:=1;
  return new;
 end if;
 if tg_table_name in ('patient_history_events','appointment_reschedules') and coalesce(current_setting('rn.anonymize',true),'')<>'on' then
  raise exception 'Histórico é imutável';
 end if;
 if new.organization_id is distinct from old.organization_id or new.id is distinct from old.id then
  raise exception 'Alteração de organização ou identificador não permitida';
 end if;
 if ctx is not null and old.organization_id<>ctx then raise exception 'Registro fora da organização atual'; end if;
 new.created_at:=old.created_at; new.created_by:=old.created_by;
 new.updated_at:=clock_timestamp(); new.updated_by:=coalesce(actor,old.updated_by);
 new.row_version:=old.row_version+1;
 return new;
end;$function$
;

CREATE OR REPLACE FUNCTION public.guard_agenda_settings_row()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare ctx uuid:=public.current_organization_id();
begin
 if tg_op='DELETE' then raise exception 'Configuração da agenda não pode ser excluída'; end if;
 if new.organization_id is null or (ctx is not null and new.organization_id<>ctx) then raise exception 'Registro fora da organização atual'; end if;
 if tg_op='UPDATE' then
  if new.organization_id is distinct from old.organization_id then raise exception 'Registro fora da organização atual'; end if;
  new.row_version:=old.row_version+1; new.updated_at:=clock_timestamp();
 end if;
 return new;
end;$function$
;

CREATE OR REPLACE FUNCTION public.guard_appointment_availability()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 b record; r record; s record;
 day_value date; occ integer; wd integer; beginning integer; ending integer;
 work_start integer; work_end integer; t time; used_count integer;
 settings jsonb;
begin
 if coalesce(current_setting('rn.agenda_migration',true),'')='on' then return new; end if;
 perform pg_advisory_xact_lock(194701,1);
 if new.cancelled_at is not null or new.archived_at is not null then return new; end if;
 if tg_op='UPDATE' and old.cancelled_at is null and old.archived_at is null and
   (old.date,old.time,old.duration_min,old.professional_id,old.anesthetist_id,old.hospital_id,old.procedure)
   is not distinct from (new.date,new.time,new.duration_min,new.professional_id,new.anesthetist_id,new.hospital_id,new.procedure) then
  return new;
 end if;
 day_value:=new.date; wd:=extract(dow from day_value)::int;
 occ:=((extract(day from day_value)::int-1)/7)+1;
 beginning:=public.agenda_minutes(new.time); ending:=beginning+new.duration_min;
 if ending<=beginning then
  raise exception using errcode='P0001',message='Horário indisponível: duração inválida.';
 end if;

 -- Bloqueios manuais valem para cirurgião e anestesista.
 for b in select * from public.schedule_blocks
   where organization_id=new.organization_id and date=new.date
     and professional_id in (coalesce(new.professional_id,''),coalesce(new.anesthetist_id,'')) loop
  if beginning<public.agenda_minutes(b.end_time) and ending>public.agenda_minutes(b.start_time) then
   raise exception using errcode='P0001',message='Horário indisponível: bloqueio do profissional.';
  end if;
 end loop;
 if new.professional_id is null then return new; end if;

 select a.settings into settings from public.doctor_agendas a where a.doctor_id=new.professional_id;
 select * into s from public.agenda_settings where organization_id=new.organization_id;
 work_start:=public.agenda_minutes(coalesce(nullif(settings->>'workStart','')::time,s.work_start,'07:00'::time));
 work_end:=public.agenda_minutes(coalesce(nullif(settings->>'workEnd','')::time,s.work_end,'19:00'::time));

 for r in select * from public.scheduling_rules
   where organization_id=new.organization_id and professional_id=new.professional_id and enabled
     and (block_all_day or severity='block') loop
  if r.weekday is not null and r.weekday<>wd then continue; end if;
  if r.occurrence is not null then
   if r.occurrence='last' then
    if extract(month from day_value+7)::int=extract(month from day_value)::int then continue; end if;
   elsif r.occurrence::int<>occ then continue; end if;
  end if;
  if r.block_all_day then
   raise exception using errcode='P0001',message='Horário indisponível: dia totalmente bloqueado.';
  end if;
  if r.start_time is not null and public.agenda_minutes(r.start_time)>work_start
     and beginning<least(public.agenda_minutes(r.start_time),work_end) and ending>work_start then
   raise exception using errcode='P0001',message='Horário indisponível: antes da janela permitida.';
  end if;
  if r.end_time is not null and public.agenda_minutes(r.end_time)<work_end
     and beginning<work_end and ending>greatest(public.agenda_minutes(r.end_time),work_start) then
   raise exception using errcode='P0001',message='Horário indisponível: após a janela permitida.';
  end if;
  foreach t in array r.forbidden_times loop
   if beginning<least(public.agenda_minutes(t)+30,work_end) and ending>public.agenda_minutes(t) then
    raise exception using errcode='P0001',message='Horário indisponível: horário proibido.';
   end if;
  end loop;
  if r.hospital_id is not null and r.hospital_id is distinct from new.hospital_id then continue; end if;
  if r.procedure_contains<>'' and position(lower(r.procedure_contains) in lower(new.procedure))=0 then continue; end if;
  if cardinality(r.preferred_times)>0 and not (new.time=any(r.preferred_times)) then
   raise exception using errcode='P0001',message='Horário indisponível: fora dos horários permitidos.';
  end if;
  if coalesce(r.max_patients,0)>0 then
   select count(*) into used_count from public.appointments a
    where a.organization_id=new.organization_id and a.id<>new.id and a.professional_id=new.professional_id
      and a.date=new.date and a.cancelled_at is null and a.archived_at is null
      and (r.hospital_id is null or a.hospital_id=r.hospital_id);
   if used_count>=r.max_patients then
    raise exception using errcode='P0001',message='Horário indisponível: limite diário atingido.';
   end if;
  end if;
 end loop;
 return new;
end;$function$
;

CREATE OR REPLACE FUNCTION public.guard_appointment_issued_invoice()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if (old.cancelled_at is null and new.cancelled_at is not null) or (old.archived_at is null and new.archived_at is not null) then
  perform pg_advisory_xact_lock(194701,1);
  if exists(
   select 1 from public.billing_records b
   join public.attendances a on a.id=b.attendance_id
   join public.invoice_billing_records item on item.billing_record_id=b.id
   join public.invoices invoice on invoice.id=item.invoice_id
   where (b.appointment_id=old.id or a.appointment_id=old.id)
     and item.is_active and invoice.status='ACTIVE' and invoice.voided_at is null) then
   raise exception using errcode='P0001',message='Não é possível cancelar ou arquivar: atendimento vinculado a Nota Fiscal emitida.';
  end if;
 end if;
 return new;
end;$function$
;

CREATE OR REPLACE FUNCTION public.guard_appointment_row()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare owner text; patient_insurance text;
begin
 if coalesce(current_setting('rn.agenda_migration',true),'')='on' then return new; end if;
 if tg_op='INSERT' or new.professional_id is distinct from old.professional_id or new.anesthetist_id is distinct from old.anesthetist_id then
  if new.anesthetist_id is not null and not exists(select 1 from public.doctors where id=new.anesthetist_id and public.is_anesthesiologist(specialty)) then
   raise exception 'Selecione um médico com especialidade Anestesiologia';
  end if;
  if exists(select 1 from unnest(array[new.professional_id,new.anesthetist_id]) p(id) where p.id is not null
     and not exists(select 1 from public.doctors d where d.id=p.id and d.active)) then
   raise exception 'Médico inexistente ou inativo';
  end if;
  if not exists(select 1 from public.doctor_agendas a join public.doctors d on d.id=a.doctor_id
     where a.doctor_id in (new.professional_id,new.anesthetist_id) and a.active and d.scheduling_enabled) then
   raise exception 'Configure uma agenda ativa para o médico antes de agendar';
  end if;
 end if;
 if new.patient_id is not null and (tg_op='INSERT' or new.patient_id is distinct from old.patient_id
    or new.professional_id is distinct from old.professional_id or new.anesthetist_id is distinct from old.anesthetist_id) then
  select owner_professional_id,insurance into owner,patient_insurance from public.patients where id=new.patient_id;
  if owner is distinct from coalesce(new.professional_id,new.anesthetist_id) then
   raise exception 'O paciente pertence a outro médico. Cadastre-o na agenda deste profissional.';
  end if;
  if new.insurance is null then new.insurance:=patient_insurance; end if;
 end if;
 if new.cancelled_at is not null and (tg_op='INSERT' or old.cancelled_at is null) then
  new.cancelled_by:=coalesce(new.cancelled_by,nullif(current_setting('rn.actor',true),'')::bigint);
 end if;
 return new;
end;$function$
;

CREATE OR REPLACE FUNCTION public.guard_billing_monthly_closing_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 raise exception 'Fechamento mensal é imutável. Correções precisam de processo de retificação auditável';
end;
$function$
;

CREATE OR REPLACE FUNCTION public.guard_invoice_appointments()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  appointment jsonb;
  previous jsonb;
  entry record;
  method text;
  payer text;
begin
  for appointment in select value from jsonb_array_elements(coalesce(new.payload->'appointments','[]'::jsonb)) loop
    method:=public.appointment_billing_method(appointment);
    if method is not null and method not in ('PARTICULAR','CONVENIO') then
      raise exception 'Forma de cobrança inválida';
    end if;
  end loop;

  for entry in
    select b.appointment_id,b.professional_id,b.professional_role,b.attendance_id,
           i.payer,b.billing_method,b.billing_entity_id,
           (b.professional_role is distinct from 'PRIMARY' or
              exists(select 1 from public.billing_records other
                     where other.attendance_id=b.attendance_id and other.id<>b.id)) independent
    from public.billing_records b
    join public.invoice_billing_records ib on ib.billing_record_id=b.id
    join public.invoices i on i.id=ib.invoice_id
    where b.appointment_id is not null and i.recipient_type='CONVENIO' and ib.is_active
  loop
    select value into appointment from jsonb_array_elements(coalesce(new.payload->'appointments','[]'::jsonb))
      where value->>'id'=entry.appointment_id;
    select value into previous from jsonb_array_elements(coalesce(old.payload->'appointments','[]'::jsonb))
      where value->>'id'=entry.appointment_id;
    -- Estado antigo de outra NF não pode impedir alteração de agendamento não relacionado.
    if appointment is not null and appointment is not distinct from previous then continue; end if;
    if appointment is null or appointment->>'status' is distinct from 'realized'
       or appointment->>'doctorId' is distinct from previous->>'doctorId'
       or appointment->>'anesthetistId' is distinct from previous->>'anesthetistId'
       or appointment->>'patientId' is distinct from previous->>'patientId' then
      raise exception 'Atendimento com NF: preserve realização, médico, anestesista e paciente';
    end if;
    if entry.independent and entry.professional_id is not null then
      if entry.professional_id is distinct from appointment->>'doctorId'
         and entry.professional_id is distinct from appointment->>'anesthetistId' then
        raise exception 'Profissional faturado não participa mais do atendimento';
      end if;
    else
      payer:=coalesce(appointment->>'insurance','');
      if public.appointment_billing_method(appointment,entry.billing_method) is distinct from 'CONVENIO'
         or (public.billing_payer_key(payer)<>public.billing_payer_key(entry.payer)
             and (appointment->>'insurance' is distinct from previous->>'insurance'
                or nullif(trim(previous->>'insurance'),'') is not null)) then
        raise exception 'NF legada: preserve convênio e forma de cobrança';
      end if;
    end if;
  end loop;

  for entry in
    select b.appointment_id,b.attendance_id,b.professional_id,b.professional_role,r.patient_id,
      (b.professional_role is distinct from 'PRIMARY' or
       exists(select 1 from public.billing_records other
              where other.attendance_id=b.attendance_id and other.id<>b.id)) independent
    from public.invoice_requests r join public.billing_records b on b.id=r.billing_record_id
    where r.status in ('PENDING','ISSUED') and b.appointment_id is not null
  loop
    select value into appointment
    from jsonb_array_elements(coalesce(new.payload->'appointments','[]'::jsonb)||
                              coalesce(new.payload->'cancelledAppointments','[]'::jsonb))
    where value->>'id'=entry.appointment_id;
    select value into previous
    from jsonb_array_elements(coalesce(old.payload->'appointments','[]'::jsonb)||
                              coalesce(old.payload->'cancelledAppointments','[]'::jsonb))
    where value->>'id'=entry.appointment_id;
    -- Só revalidar o atendimento protegido quando ele tiver sido alterado.
    if appointment is not null and appointment is not distinct from previous then continue; end if;
    if appointment is null or appointment->>'patientId' is distinct from entry.patient_id then
      raise exception 'Atendimento com solicitação fiscal: preserve o paciente';
    end if;
    if entry.independent and entry.professional_id is not null then
      if entry.professional_id is distinct from appointment->>'doctorId'
         and entry.professional_id is distinct from appointment->>'anesthetistId' then
        raise exception 'Profissional da solicitação fiscal não participa do atendimento';
      end if;
    elsif appointment->>'forma_cobranca' is distinct from 'PARTICULAR' then
      raise exception 'Solicitação fiscal legada: preserve a forma particular';
    end if;
  end loop;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.guard_issued_invoice_agenda_cancellation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  -- All normal agenda and billing mutations already serialize on this key.
  PERFORM pg_advisory_xact_lock(194701,1);
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(coalesce(OLD.payload->'appointments','[]'::jsonb)) previous
    WHERE NOT EXISTS (
      SELECT 1
      FROM jsonb_array_elements(coalesce(NEW.payload->'appointments','[]'::jsonb)) current_appointment
      WHERE current_appointment->>'id'=previous->>'id'
        AND current_appointment->>'status' IS DISTINCT FROM 'cancelled'
    )
    AND EXISTS (
      SELECT 1
      FROM public.billing_records b
      JOIN public.attendances a ON a.id=b.attendance_id
      JOIN public.invoice_billing_records item ON item.billing_record_id=b.id
      JOIN public.invoices invoice ON invoice.id=item.invoice_id
      WHERE (b.appointment_id=previous->>'id' OR a.appointment_id=previous->>'id')
        AND item.is_active
        AND invoice.status='ACTIVE'
        AND invoice.voided_at IS NULL
    )
  ) THEN
    RAISE EXCEPTION USING ERRCODE='P0001',
      MESSAGE='Não é possível cancelar ou excluir este atendimento, pois existe uma Nota Fiscal emitida vinculada a ele.';
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.guard_issued_invoice_attendance_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF TG_OP='UPDATE' AND
     (NEW.status IS DISTINCT FROM 'cancelled' OR OLD.status='cancelled') THEN
    RETURN NEW;
  END IF;

  -- Prevent concurrent invoice creation through financial RPC from racing
  -- against an attendance cancellation.
  PERFORM pg_advisory_xact_lock(194701,1);

  IF EXISTS (
    SELECT 1
    FROM public.billing_records b
    JOIN public.invoice_billing_records item ON item.billing_record_id=b.id
    JOIN public.invoices invoice ON invoice.id=item.invoice_id
    WHERE b.attendance_id=OLD.id
      AND item.is_active
      AND invoice.status='ACTIVE'
      AND invoice.voided_at IS NULL
  ) THEN
    RAISE EXCEPTION USING ERRCODE='P0001',
      MESSAGE='Não é possível cancelar ou excluir este atendimento, pois existe uma Nota Fiscal emitida vinculada a ele.';
  END IF;

  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.guard_legacy_agenda_organization()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE rn_org_id uuid;
BEGIN
 SELECT id INTO rn_org_id FROM public.organizations WHERE slug='rn-gestao' AND active;
 IF rn_org_id IS NULL OR (SELECT count(*) FROM public.organizations)<>1
   THEN RAISE EXCEPTION 'Organização de operação inválida. Acesso bloqueado'; END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Exclusão direta do estado da agenda bloqueada'; END IF;
 IF NEW.id<>1 OR NEW.organization_id IS DISTINCT FROM rn_org_id
   THEN RAISE EXCEPTION 'Agenda fora da organização atual'; END IF;
 IF TG_OP='UPDATE' AND OLD.organization_id IS DISTINCT FROM NEW.organization_id
   THEN RAISE EXCEPTION 'Alteração de organização da agenda não permitida'; END IF;
 RETURN NEW;
END;$function$
;

CREATE OR REPLACE FUNCTION public.guard_patient_row()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if new.created_by is null then raise exception 'Cadastro de paciente exige autoria'; end if;
 new.guardian_name:=nullif(btrim(coalesce(new.guardian_name,'')),'');
 if not new.newborn then new.guardian_name:=null; end if;
 if tg_op='UPDATE' and new.owner_professional_id is distinct from old.owner_professional_id then
  -- Correção de cadastro feito no médico errado: só sem consultas e sem
  -- histórico clínico (eventos ligados a consultas).
  if exists(select 1 from public.appointments a where a.patient_id=old.id)
    or exists(select 1 from public.patient_history_events h where h.patient_id=old.id and h.appointment_id is not null) then
   raise exception 'O médico responsável não pode ser alterado: o paciente já possui consultas ou histórico.';
  end if;
 end if;
 return new;
end;$function$
;

CREATE OR REPLACE FUNCTION public.guard_rn_finance_organization()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare ctx uuid:=public.current_organization_id();
begin
 if new.organization_id is null then raise exception 'Registro financeiro sem organização'; end if;
 if ctx is not null and new.organization_id<>ctx then raise exception 'Registro financeiro fora da organização autorizada'; end if;
 if tg_op='UPDATE' and old.organization_id is distinct from new.organization_id then
  raise exception 'Transferência de organização financeira proibida';
 end if;
 return new;
end;$function$
;

CREATE OR REPLACE FUNCTION public.guard_security_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if tg_op='UPDATE' then raise exception 'Evento de segurança é imutável'; end if;
 if tg_op='DELETE' and coalesce(current_setting('rn.maintenance',true),'')<>'on' then raise exception 'Evento de segurança é imutável'; end if;
 return coalesce(new,old);
end;$function$
;

CREATE OR REPLACE FUNCTION public.guard_tenant_row()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare ctx uuid:=public.current_organization_id(); spec text; kind text; col text; ref text; derived uuid; row_data jsonb; target uuid; first_user bigint; i integer;
begin
 if tg_op='DELETE' then
  if ctx is not null and old.organization_id<>ctx then raise exception 'Registro fora da organização atual'; end if;
  return old;
 end if;
 if tg_op='UPDATE' then
  if new.organization_id is distinct from old.organization_id then raise exception 'Alteração de organização não permitida'; end if;
  if ctx is not null and old.organization_id<>ctx then raise exception 'Registro fora da organização atual'; end if;
 end if;
 row_data:=to_jsonb(new); target:=new.organization_id;
 -- Médicos pertencem a uma única organização: definem (ou conferem) a organização da linha.
 for i in 0..tg_nargs-1 loop
  spec:=tg_argv[i]; kind:=split_part(spec,':',1); col:=split_part(spec,':',2); ref:=row_data->>col;
  if ref is null or ref='' then continue; end if;
  if kind='doctor' then
   derived:=(select organization_id from public.doctors where id=ref);
   if derived is null then raise exception 'Vínculo sem organização (%)',col; end if;
   if target is null then target:=derived; elsif derived<>target then raise exception 'Vínculo de outra organização (%)',col; end if;
  elsif first_user is null then first_user:=ref::bigint;
  end if;
 end loop;
 target:=coalesce(target,ctx);
 if target is null and first_user is not null then
  if (select count(*) from public.organization_memberships where user_id=first_user and active)=1 then
   target:=(select organization_id from public.organization_memberships where user_id=first_user and active);
  end if;
 end if;
 if target is null then raise exception 'Registro sem organização'; end if;
 if ctx is not null and target<>ctx then raise exception 'Registro fora da organização atual'; end if;
 -- Pessoas citadas na linha precisam ter (ou ter tido) vínculo com essa organização.
 for i in 0..tg_nargs-1 loop
  spec:=tg_argv[i]; kind:=split_part(spec,':',1); col:=split_part(spec,':',2); ref:=row_data->>col;
  if kind<>'user' or ref is null or ref='' then continue; end if;
  if not exists(select 1 from public.organization_memberships where user_id=ref::bigint and organization_id=target) then
   raise exception 'Vínculo de outra organização (%)',col;
  end if;
 end loop;
 new.organization_id:=target;
 return new;
end;$function$
;

