 IMMUTABLE
 SET search_path TO ''
AS $function$
 select left(coalesce(nullif(trim(both '-' from regexp_replace(lower(translate(btrim(p_name),'áàâãäéèêëíìîïóòôõöúùûüçñ','aaaaaeeeeiiiiooooouuuucn')),'[^a-z0-9]+','-','g')),''),'organizacao'),48)
