CREATE OR REPLACE FUNCTION public.reject_financial_attachment(p_actor bigint, p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 perform public.financial_operation(p_actor,'payment_proof',p_id::text);
 update public.financial_attachments set status='REJECTED' where id=p_id and created_by=p_actor and status='PENDING';
 if not found then raise exception 'Envio não disponível';end if;
end;$function$
;

CREATE OR REPLACE FUNCTION public.remove_financial_attachment(p_actor bigint, p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 attachment public.financial_attachments%rowtype;
begin
 select * into attachment
 from public.financial_attachments
 where id=p_id
 for update;

 if attachment.id is null or attachment.status<>'READY'
    or not attachment.is_current or attachment.deactivated_at is not null then
  raise exception 'O comprovante já não está ativo';
 end if;
 if not public.authorized_financial_attachment_actor(
    p_actor,attachment.invoice_id,attachment.billing_record_id) then
  raise exception 'Sem permissão para excluir este comprovante';
 end if;

 perform public.financial_operation(p_actor,'payment_proof',
  coalesce(attachment.invoice_id,attachment.billing_record_id)::text);

 update public.financial_attachments
 set is_current=false,
     deactivated_at=clock_timestamp(),
     deactivation_reason='REMOVED_BY_USER'
 where id=attachment.id and status='READY' and is_current;

 if not found then raise exception 'Não foi possível remover o comprovante';end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.renew_email_verification(p_email text, p_token_hash text)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_user bigint;
begin
 select id into v_user from public.users where lower(email)=lower(btrim(p_email)) and active and email_verified_at is null;
 if v_user is null then return null; end if;
 update public.auth_tokens set used_at=now() where kind='verify_email' and user_id=v_user and used_at is null;
 insert into public.auth_tokens(token_hash,kind,user_id,email,expires_at) values(p_token_hash,'verify_email',v_user,lower(btrim(p_email)),now()+interval '48 hours');
 return v_user;
end;$function$
;

CREATE OR REPLACE FUNCTION public.request_password_reset(p_email text, p_token_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare u public.users%rowtype;
begin
 select * into u from public.users where lower(email)=lower(btrim(p_email)) and active;
 if not found then return null; end if;
 update public.auth_tokens set used_at=now() where kind='reset_password' and user_id=u.id and used_at is null;
 insert into public.auth_tokens(token_hash,kind,user_id,email,expires_at) values(p_token_hash,'reset_password',u.id,lower(u.email),now()+interval '1 hour');
 return jsonb_build_object('name',u.name,'email',u.email);
end;$function$
;

CREATE OR REPLACE FUNCTION public.require_organization_manager(p_actor bigint, p_org uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 perform public.use_organization(p_actor,p_org);
 if not exists(select 1 from public.users u join public.organization_memberships m on m.user_id=u.id and m.organization_id=p_org and m.active and m.role='general_manager'
   where u.id=p_actor and u.role='general_manager' and u.active) then raise exception 'Acesso restrito à gerência'; end if;
end;$function$
;

CREATE OR REPLACE FUNCTION public.require_rn_agenda_actor_organization(p_actor bigint)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare v uuid;
begin
 if p_actor is null then raise exception 'Acesso à organização negado'; end if;
 v:=public.actor_organization_id(p_actor);
 if not exists (select 1 from public.agenda_settings where organization_id=v) then
  raise exception 'Agenda da organização indisponível';
 end if;
 return v;
end;$function$
;

CREATE OR REPLACE FUNCTION public.reset_password(p_token_hash text, p_hash text, p_salt text)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare t public.auth_tokens%rowtype;
begin
 select * into t from public.auth_tokens where token_hash=p_token_hash and kind='reset_password' for update;
 if not found or t.used_at is not null or t.expires_at<=now() then raise exception 'Link inválido ou expirado'; end if;
 if not public.valid_password_credentials(p_hash,p_salt) then raise exception 'Credencial inválida'; end if;
 update public.auth_tokens set used_at=now() where id=t.id;
 -- Trocar a senha encerra as sessões abertas (trigger users_revoke_sessions) e comprova o e-mail.
 update public.users set password_hash=p_hash,password_salt=p_salt,email_verified_at=coalesce(email_verified_at,now()),updated_at=clock_timestamp()
  where id=t.user_id and active and lower(email)=lower(t.email);
 if not found then raise exception 'Link inválido ou expirado'; end if;
 return t.user_id;
end;$function$
;

CREATE OR REPLACE FUNCTION public.resolve_monitor_checks(p_environment text, p_active text[])
 RETURNS jsonb
 LANGUAGE sql
 SET search_path TO ''
AS $function$
 with done as (
   update public.monitor_incidents set resolved_at=now()
   where source='check' and environment=p_environment and resolved_at is null
     and not (fingerprint = any(coalesce(p_active,'{}'::text[])))
   returning title,severity,alerted_at
 )
 select coalesce(jsonb_agg(jsonb_build_object('title',title,'severity',severity)) filter (where alerted_at is not null),'[]'::jsonb) from done
$function$
;

CREATE OR REPLACE FUNCTION public.resolve_quiet_incidents(p_environment text)
 RETURNS jsonb
 LANGUAGE sql
 SET search_path TO ''
AS $function$
 with done as (
   update public.monitor_incidents set resolved_at=now()
   where environment=p_environment and resolved_at is null and source in ('server','client')
     and auto_fix in ('transient','reload') and last_seen<now()-interval '1 hour'
   returning title,severity,alerted_at
 )
 select coalesce(jsonb_agg(jsonb_build_object('title',title,'severity',severity)) filter (where alerted_at is not null),'[]'::jsonb) from done
$function$
;

CREATE OR REPLACE FUNCTION public.restore_billing_invoice(p_actor bigint, p_data jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 i public.invoices%rowtype;
 line record;
 pending_request public.invoice_requests%rowtype;
 request_total integer;
begin
 if (select role from public.users where id=p_actor) is distinct from 'general_manager'
 then raise exception 'Exige autorização do Gerente Geral'; end if;
 if nullif(trim(p_data->>'reason'),'') is null
 then raise exception 'Informe o motivo da restauração'; end if;
 if nullif(p_data->>'id','') is null
 then raise exception 'NF inválida'; end if;

 select * into i from public.invoices where id=(p_data->>'id')::uuid for update;
 if i.id is null then raise exception 'NF não encontrada'; end if;
 if i.status not in ('CANCELLED','REPLACED') or i.voided_at is not null
 then raise exception 'Somente NFs canceladas ou substituídas não desfeitas podem ser reativadas'; end if;
 if i.updated_at is distinct from (p_data->>'updated_at')::timestamptz
 then raise exception 'NF alterada por outro usuário. Atualize a página'; end if;
 if not exists(select 1 from public.invoice_billing_records where invoice_id=i.id)
 then raise exception 'NF sem atendimentos vinculados não pode ser reativada automaticamente'; end if;

 -- Reativação de uma NF substituída exige desativação prévia da substituta.
 if i.replaced_by_invoice_id is not null and exists (
   select 1 from public.invoices next_invoice
   where next_invoice.id=i.replaced_by_invoice_id
     and next_invoice.status='ACTIVE' and next_invoice.voided_at is null
 ) then
  raise exception 'A NF substituta ainda está ativa. Cancele ou regularize a substituta antes de reativar esta NF';
 end if;
 -- Concurrency: row locks serialize restores involving the same cobrança.
 for line in
  select ib.billing_record_id
  from public.invoice_billing_records ib
  where ib.invoice_id=i.id order by ib.billing_record_id for update
 loop
  perform 1 from public.billing_records b where b.id=line.billing_record_id for update;
  if exists (
   select 1 from public.invoice_billing_records other_ib
   join public.invoices other_invoice on other_invoice.id=other_ib.invoice_id
   where other_ib.billing_record_id=line.billing_record_id
    and other_ib.invoice_id<>i.id and other_ib.is_active
  ) then
   raise exception 'Atendimento já vinculado a outra NF ativa. Regularize a NF atual antes de restaurar a anterior';
  end if;
  if exists (
   select 1 from public.invoice_requests ir
   where ir.billing_record_id=line.billing_record_id and ir.status='ISSUED'
    and ir.invoice_id is distinct from i.id
  ) then
   raise exception 'Solicitação fiscal já vinculada a outra NF. Regularize-a antes de restaurar a anterior';
  end if;
 end loop;

 perform public.financial_operation(p_actor,'restore_invoice',i.id::text);
 update public.invoice_billing_records
 set is_active=true where invoice_id=i.id;
 if i.recipient_type='CONVENIO' then
  update public.billing_records b
  set payment_status=case when i.paid_at is not null then 'PAGO' else 'PENDENTE' end
  where b.id in (select ib.billing_record_id from public.invoice_billing_records ib where ib.invoice_id=i.id);
 else
  -- Uma única solicitação ativa por cobrança: não trocar solicitações de outra NF.
  for line in select distinct ib.billing_record_id from public.invoice_billing_records ib where ib.invoice_id=i.id loop
   select count(*) into request_total from public.invoice_requests req
    where req.billing_record_id=line.billing_record_id and req.status in ('PENDING','ISSUED');
   if request_total>1 then raise exception 'Há solicitações fiscais concorrentes para o mesmo pagamento'; end if;
   update public.invoice_requests
   set status='ISSUED',invoice_id=i.id
   where billing_record_id=line.billing_record_id and status='PENDING' and invoice_id is null;
  end loop;
 end if;
 update public.invoices
 set status='ACTIVE', cancelled_at=null,cancelled_by=null,cancellation_reason=null,
     replaced_by_invoice_id=null
 where id=i.id;
 perform set_config('rn.operation','',true);
 perform set_config('rn.actor','',true);
 return i.id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.revoke_changed_credentials()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if old.password_hash is distinct from new.password_hash or old.password_salt is distinct from new.password_salt or old.role is distinct from new.role then
    delete from public.sessions where user_id=old.id;
  end if;
  return new;
end;
$function$
;

