CREATE OR REPLACE FUNCTION public.run_maintenance()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare s integer; t integer; r integer; e integer; mr integer; md integer; result jsonb;
begin
 delete from public.sessions where expires_at<now()-interval '1 day'; get diagnostics s=row_count;
 delete from public.auth_tokens where expires_at<now()-interval '30 days'; get diagnostics t=row_count;
 delete from public.security_rate_limits where expires_at<now(); get diagnostics r=row_count;
 perform set_config('rn.maintenance','on',true);
 delete from public.security_events where created_at<now()-interval '365 days'; get diagnostics e=row_count;
 perform set_config('rn.maintenance','',true);
 update public.monitor_incidents set resolved_at=now()
  where resolved_at is null and source in ('server','client') and last_seen<now()-interval '7 days'; get diagnostics mr=row_count;
 delete from public.monitor_incidents where resolved_at<now()-interval '90 days'; get diagnostics md=row_count;
 result:=jsonb_build_object('sessions',s,'tokens',t,'rateLimits',r,'securityEvents',e,'incidentsResolved',mr,'incidentsDeleted',md);
 perform public.touch_monitor_heartbeat('maintenance',true,result);
 return result;
end;$function$
;

CREATE OR REPLACE FUNCTION public.save_billing(p_actor bigint, p_kind text, p_data jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  attendance_key text;
begin
  if p_kind='record' then
    attendance_key:=coalesce(nullif(p_data->>'attendance_id',''),nullif(p_data->>'appointment_id',''));
    if attendance_key is not null and (
      select count(*) from public.billing_records where attendance_id=attendance_key
    )>1 then
      raise exception 'Atendimento possui cobranças independentes; selecione a cobrança profissional específica';
    end if;
  elsif (
    (p_kind='invoice' and coalesce(p_data->>'recipient_type','CONVENIO')='CONVENIO')
    or (p_kind='replace_invoice' and exists(
      select 1 from public.invoices where id=nullif(p_data->>'id','')::uuid and recipient_type='CONVENIO'))
  ) and exists (
    with selected_attendances as (
      select value::text as attendance_id
      from jsonb_array_elements_text(coalesce(p_data->'attendance_ids',p_data->'appointment_ids','[]'::jsonb))
      union
      select b.attendance_id
      from public.billing_records b
      join jsonb_array_elements_text(coalesce(p_data->'record_ids','[]'::jsonb)) selected(id) on selected.id=b.id::text
    )
    select 1 from selected_attendances s
    where (select count(*) from public.billing_records b where b.attendance_id=s.attendance_id)>1
  ) then
    raise exception 'NF com cobranças independentes deve usar os IDs das cobranças profissionais';
  end if;
  return public.save_billing_legacy_single_charge(p_actor,p_kind,p_data);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.save_billing_denial(p_actor bigint, p_data jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 actor_role text;
 rn_org_id uuid;
 act text:=p_data->>'action';
 charge public.billing_records%rowtype;
 attendance public.attendances%rowtype;
 case_row public.billing_denial_cases%rowtype;
 appeal_row public.billing_denial_appeals%rowtype;
 result_id uuid;
 old_snapshot jsonb;
 event_name text;
 value_amount numeric(14,2);
 action_date date;
 note_value text:=nullif(trim(p_data->>'notes'),'');
begin
 rn_org_id:=public.require_rn_agenda_actor_organization(p_actor);
 select role into actor_role from public.users where id=p_actor and active;
 if actor_role is null or actor_role not in ('general_manager','secretary')
    then raise exception 'Sem permissão para gerir glosas';end if;
 if act not in ('OPEN_CASE','FILE_APPEAL','DECIDE_APPEAL','REGISTER_RECOVERY','CLOSE_CASE')
    then raise exception 'Ação de glosa inválida';end if;
 if length(coalesce(note_value,''))>2000 then raise exception 'Observação muito longa';end if;

 if act='OPEN_CASE' then
   select * into charge from public.billing_records
    where id=nullif(p_data->>'billing_record_id','')::uuid and organization_id=rn_org_id;
 else
   select * into case_row from public.billing_denial_cases
    where id=nullif(p_data->>'denial_id','')::uuid and organization_id=rn_org_id for update;
   if not found then raise exception 'Glosa inexistente';end if;
   if case_row.updated_at is distinct from nullif(p_data->>'updated_at','')::timestamptz
     then raise exception 'Glosa alterada. Atualize a página';end if;
   select * into charge from public.billing_records where id=case_row.billing_record_id and organization_id=rn_org_id;
 end if;
 if charge.id is null or charge.professional_id is null or charge.billing_method<>'CONVENIO'
    then raise exception 'Glosa exige cobrança profissional de convênio';end if;
 select * into attendance from public.attendances where id=charge.attendance_id and organization_id=rn_org_id;
 if attendance.id is null or attendance.status<>'realized'
    then raise exception 'Atendimento não realizado';end if;
 if actor_role='secretary' and not exists(select 1 from public.agenda_access a
    where a.user_id=p_actor and a.professional_id=charge.professional_id)
    then raise exception 'Sem acesso à agenda deste profissional';end if;
 if act<>'OPEN_CASE' and (case_row.billing_entity_id is distinct from charge.billing_entity_id)
    then raise exception 'Entidade financeira histórica divergente';end if;
 if act<>'OPEN_CASE' and case_row.status='CLOSED'
    then raise exception 'Glosa encerrada. Abra nova ocorrência para registro adicional';end if;
 old_snapshot:=case when act='OPEN_CASE' then null else to_jsonb(case_row) end;

 if act='OPEN_CASE' then
   action_date:=nullif(p_data->>'denied_on','')::date;
   value_amount:=nullif(p_data->>'denied_amount','')::numeric;
   if p_data->>'denial_kind' not in ('TOTAL','PARCIAL')
      then raise exception 'Informe se a glosa foi total ou parcial';end if;
   if action_date is null or action_date<attendance.date or action_date>current_date
      or value_amount is null or value_amount<=0 or value_amount>999999999999.99
      or length(trim(coalesce(p_data->>'reason',''))) not between 5 and 2000
      or length(coalesce(p_data->>'payer_reference',''))>120
      then raise exception 'Informe data, valor e motivo válidos para a glosa';end if;
   insert into public.billing_denial_cases(
      billing_record_id,billing_entity_id,denied_on,denial_kind,denied_amount,reason,payer_reference,
      notes,created_by,updated_by)
   values(charge.id,charge.billing_entity_id,action_date,p_data->>'denial_kind',value_amount,
      trim(p_data->>'reason'),nullif(trim(p_data->>'payer_reference'),''),
      note_value,p_actor,p_actor) returning * into case_row;
   event_name:='OPENED';

 elsif act='FILE_APPEAL' then
   if case_row.recovered_amount>=case_row.denied_amount then
     raise exception 'Glosa integralmente recuperada. Não é possível abrir outro recurso';end if;
   action_date:=nullif(p_data->>'filed_on','')::date;
   value_amount:=nullif(p_data->>'appealed_amount','')::numeric;
   if action_date is null or action_date<case_row.denied_on or action_date>current_date
     or value_amount is null or value_amount<=0 or value_amount>case_row.denied_amount
     or length(trim(coalesce(p_data->>'protocol',''))) not between 3 and 120
   then raise exception 'Informe data, valor e protocolo do recurso válidos';end if;
   if exists(select 1 from public.billing_denial_appeals where denial_id=case_row.id and organization_id=rn_org_id and decision='PENDING')
   then raise exception 'Já existe recurso aguardando decisão';end if;
   insert into public.billing_denial_appeals(
      denial_id,filed_on,appealed_amount,protocol,notes,created_by)
   values(case_row.id,action_date,value_amount,trim(p_data->>'protocol'),note_value,p_actor)
   returning * into appeal_row;
   update public.billing_denial_cases set status='APPEALED',
      updated_at=clock_timestamp(),updated_by=p_actor where id=case_row.id and organization_id=rn_org_id;
   event_name:='APPEAL_FILED';

 elsif act='DECIDE_APPEAL' then
   select * into appeal_row from public.billing_denial_appeals
     where id=nullif(p_data->>'appeal_id','')::uuid and denial_id=case_row.id and organization_id=rn_org_id for update;
   if appeal_row.id is null or appeal_row.decision<>'PENDING'
      then raise exception 'Recurso não está pendente';end if;
   action_date:=nullif(p_data->>'decision_on','')::date;
   value_amount:=coalesce(nullif(p_data->>'approved_amount','')::numeric,0);
   if p_data->>'decision' not in ('ACCEPTED','PARTIAL','REJECTED')
     or action_date is null or action_date<appeal_row.filed_on or action_date>current_date
     or value_amount<0 or value_amount>appeal_row.appealed_amount
     or (p_data->>'decision'='ACCEPTED' and value_amount<>appeal_row.appealed_amount)
     or (p_data->>'decision'='PARTIAL' and (value_amount<=0 or value_amount>=appeal_row.appealed_amount))
     or (p_data->>'decision'='REJECTED' and value_amount<>0)
   then raise exception 'Decisão ou valor deferido incompatível com o recurso';end if;
   update public.billing_denial_appeals set decision=p_data->>'decision',
     decision_on=action_date,approved_amount=value_amount,
     decision_notes=note_value,decided_by=p_actor where id=appeal_row.id and organization_id=rn_org_id
     returning * into appeal_row;
   update public.billing_denial_cases set status=case when recovered_amount>0 then 'PARTIAL' else 'DECIDED' end,
     updated_at=clock_timestamp(),updated_by=p_actor where id=case_row.id and organization_id=rn_org_id;
   event_name:='APPEAL_DECIDED';

 elsif act='REGISTER_RECOVERY' then
   select * into appeal_row from public.billing_denial_appeals
     where id=nullif(p_data->>'appeal_id','')::uuid and denial_id=case_row.id and organization_id=rn_org_id for update;
   action_date:=nullif(p_data->>'recovered_on','')::date;
   value_amount:=nullif(p_data->>'amount','')::numeric;
   if appeal_row.id is null or appeal_row.decision not in ('ACCEPTED','PARTIAL')
     or action_date is null or action_date<appeal_row.decision_on or action_date>current_date
     or value_amount is null or value_amount<=0
     or length(trim(coalesce(p_data->>'receipt_reference',''))) not between 3 and 120
     or case_row.recovered_amount+value_amount>case_row.denied_amount
     or value_amount+(select coalesce(sum(amount),0) from public.billing_denial_recoveries
                       where appeal_id=appeal_row.id and organization_id=rn_org_id)>appeal_row.approved_amount
   then raise exception 'Recuperação excede o deferimento ou faltam comprovantes';end if;
   insert into public.billing_denial_recoveries(
      denial_id,appeal_id,recovered_on,amount,receipt_reference,notes,created_by)
   values(case_row.id,appeal_row.id,action_date,value_amount,
      trim(p_data->>'receipt_reference'),note_value,p_actor);
   update public.billing_denial_cases set recovered_amount=recovered_amount+value_amount,
     status=case when recovered_amount+value_amount=denied_amount then 'RECOVERED' else 'PARTIAL' end,
     updated_at=clock_timestamp(),updated_by=p_actor where id=case_row.id and organization_id=rn_org_id;
   event_name:='RECOVERY_RECORDED';

 elsif act='CLOSE_CASE' then
   if length(trim(coalesce(p_data->>'closing_reason',''))) not between 5 and 1000
     then raise exception 'Informe o motivo do encerramento';end if;
   if exists(select 1 from public.billing_denial_appeals where denial_id=case_row.id and organization_id=rn_org_id and decision='PENDING')
     then raise exception 'Resolva o recurso pendente antes de encerrar';end if;
   update public.billing_denial_cases set status='CLOSED',closed_at=clock_timestamp(),
     closed_by=p_actor,closing_reason=trim(p_data->>'closing_reason'),
     updated_at=clock_timestamp(),updated_by=p_actor where id=case_row.id and organization_id=rn_org_id;
   event_name:='CLOSED';
 end if;

 select * into case_row from public.billing_denial_cases where id=case_row.id and organization_id=rn_org_id;
 result_id:=case_row.id;
 insert into public.billing_denial_events(denial_id,actor_id,event_type,before_snapshot,after_snapshot)
 values(result_id,p_actor,event_name,old_snapshot,
   jsonb_build_object('case',to_jsonb(case_row),
     'appeal',case when appeal_row.id is null then null else to_jsonb(appeal_row) end,
     'payload',p_data));
 return result_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.save_billing_fiscal_core(p_actor bigint, p_kind text, p_data jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ begin perform public.billing_paused(); return null; end;$function$
;

CREATE OR REPLACE FUNCTION public.save_billing_legacy_single_charge(p_actor bigint, p_kind text, p_data jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ begin perform public.billing_paused(); return null; end;$function$
;

CREATE OR REPLACE FUNCTION public.save_billing_portal_rule(p_actor bigint, p_data jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 rn_org_id uuid;
  key text:=upper(trim(regexp_replace(coalesce(p_data->>'destination_key',''),'\s+',' ','g')));
  channel text:=nullif(p_data->>'submission_channel_code','');
  doctor text:=nullif(p_data->>'professional_id','');
  start_date date:=nullif(p_data->>'valid_from','')::date;
  end_date date:=nullif(p_data->>'valid_to','')::date;
  anchor text:=p_data->>'starts_from';
  days_count integer:=nullif(p_data->>'deadline_days','')::integer;
  lead_days integer:=nullif(p_data->>'alert_before_days','')::integer;
  saved_id uuid;
begin
 rn_org_id:=public.require_rn_agenda_actor_organization(p_actor);
  if not exists(select 1 from public.users where id=p_actor and role='general_manager' and active)
    then raise exception 'Somente a gerência pode configurar prazos';end if;
  if length(key) not between 2 and 120 or channel not in ('PORTAL_CONVENIO','COOPERATIVA','MANUAL')
     or anchor not in ('SERVICE_DATE','GUIDE_RECEIVED') or start_date is null
     or days_count not between 1 and 365 or lead_days not between 0 and least(days_count,90)
     or (end_date is not null and end_date<start_date) then
     raise exception 'Preencha destino, canal, início da vigência, prazo e antecedência válidos';
  end if;
  if doctor is not null and not exists(select 1 from public.doctors where id=doctor and organization_id=rn_org_id and active)
    then raise exception 'Profissional inexistente';end if;
  -- Serializa edição de regras para impedir duas regras sobrepostas concorrentes.
  perform pg_advisory_xact_lock(194701,11);
  if exists(select 1 from public.billing_portal_deadline_rules r
    where r.organization_id=rn_org_id and r.active and r.destination_key=key and r.submission_channel_code=channel
      and r.professional_id is not distinct from doctor
      and r.valid_from<=coalesce(end_date,'infinity'::date)
      and start_date<=coalesce(r.valid_to,'infinity'::date))
    then raise exception 'Já existe regra sobreposta para esse destino, canal e profissional';end if;
  insert into public.billing_portal_deadline_rules(organization_id,destination_key,submission_channel_code,professional_id,
      starts_from,deadline_days,alert_before_days,valid_from,valid_to,created_by)
  values(rn_org_id,key,channel,doctor,anchor,days_count,lead_days,start_date,end_date,p_actor)
  returning id into saved_id;
  return saved_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.save_billing_portal_submission(p_actor bigint, p_data jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  actor_role text;
 rn_org_id uuid;
  record_id uuid:=nullif(p_data->>'billing_record_id','')::uuid;
  charge public.billing_records%rowtype;
  attendance public.attendances%rowtype;
  old_row public.billing_portal_submissions%rowtype;
  new_row public.billing_portal_submissions%rowtype;
  saved_id uuid;
  destination text:=upper(trim(regexp_replace(coalesce(p_data->>'destination_key',''),'\s+',' ','g')));
  channel text:=nullif(p_data->>'submission_channel_code','');
  guide_date date:=nullif(p_data->>'guide_received_at','')::date;
  action text:=p_data->>'action';
  submission_date date:=nullif(p_data->>'submitted_at','')::date;
  protocol text:=nullif(trim(p_data->>'portal_protocol'),'');
  note_value text:=nullif(trim(p_data->>'notes'),'');
begin
 rn_org_id:=public.require_rn_agenda_actor_organization(p_actor);
  select role into actor_role from public.users where id=p_actor and active;
  if actor_role not in ('general_manager','secretary') or actor_role is null
    then raise exception 'Acesso negado ao envio de guias';end if;
  select * into charge from public.billing_records where id=record_id and organization_id=rn_org_id;
  if not found or charge.professional_id is null or charge.billing_method<>'CONVENIO'
    or charge.settlement_mode<>'INVOICE' then
    raise exception 'Cobrança profissional de convênio não elegível';
  end if;
  select * into attendance from public.attendances where id=charge.attendance_id and organization_id=rn_org_id;
  if not found or attendance.status<>'realized' then raise exception 'Atendimento ainda não realizado';end if;
  if actor_role='secretary' and not exists(select 1 from public.agenda_access
    where user_id=p_actor and professional_id=charge.professional_id)
    then raise exception 'Sem acesso à agenda desse profissional';end if;
  if action not in ('SAVE_PENDING','MARK_SUBMITTED')
    or length(destination) not between 2 and 120
    or channel not in ('PORTAL_CONVENIO','COOPERATIVA','MANUAL')
    or (charge.submission_channel_code not in ('LEGADO','MANUAL')
        and channel is distinct from charge.submission_channel_code)
    or (guide_date is not null and guide_date>current_date)
    or length(coalesce(note_value,''))>2000 then
    raise exception 'Revise destino, canal e dados da guia';
  end if;
  if action='MARK_SUBMITTED' and
    (guide_date is null or submission_date is null or submission_date>current_date
      or submission_date<guide_date or length(coalesce(protocol,'')) not between 3 and 120)
    then raise exception 'Faturado no portal exige recebimento da guia, data e protocolo válidos';end if;
  if action='SAVE_PENDING' and (submission_date is not null or protocol is not null)
    then raise exception 'Data e protocolo pertencem apenas à confirmação de faturamento';end if;

  perform pg_advisory_xact_lock(194701,12);
  select * into old_row from public.billing_portal_submissions where billing_record_id=record_id and organization_id=rn_org_id for update;
  if old_row.status='FATURADO' then raise exception 'Guia já faturada no portal. Preserve o histórico';end if;
  if old_row.id is not null and old_row.guide_received_at is not null
      and guide_date is null then
    raise exception 'Para corrigir o recebimento de uma guia já registrada, contate a gerência';end if;

  if old_row.id is null then
    insert into public.billing_portal_submissions(
      billing_record_id,status,destination_key,submission_channel_code,guide_received_at,
      submitted_at,portal_protocol,notes,submitted_by,created_by,updated_by)
    values(record_id,case when action='MARK_SUBMITTED' then 'FATURADO' else 'PENDENTE' end,
      destination,channel,guide_date,
      case when action='MARK_SUBMITTED' then submission_date end,
      case when action='MARK_SUBMITTED' then protocol end,note_value,
      case when action='MARK_SUBMITTED' then p_actor end,p_actor,p_actor)
    returning * into new_row;
  else
    update public.billing_portal_submissions set
      status=case when action='MARK_SUBMITTED' then 'FATURADO' else 'PENDENTE' end,
      destination_key=destination,submission_channel_code=channel,
      guide_received_at=guide_date,
      submitted_at=case when action='MARK_SUBMITTED' then submission_date end,
      portal_protocol=case when action='MARK_SUBMITTED' then protocol end,
      submitted_by=case when action='MARK_SUBMITTED' then p_actor end,
      notes=note_value,updated_at=clock_timestamp(),updated_by=p_actor
      where id=old_row.id and organization_id=rn_org_id returning * into new_row;
  end if;
  insert into public.billing_portal_submission_events(submission_id,actor_id,event_type,before_snapshot,after_snapshot)
    values(new_row.id,p_actor,
      case when action='MARK_SUBMITTED' then 'SUBMITTED'
        when old_row.guide_received_at is distinct from new_row.guide_received_at then 'GUIDE_UPDATED'
        else 'CONFIGURED' end,
      case when old_row.id is null then null else to_jsonb(old_row) end,to_jsonb(new_row));
  return new_row.id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.save_billing_with_manager_approval(p_actor bigint, p_approver bigint, p_kind text, p_data jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 operator_row public.users%rowtype;
 manager_row public.users%rowtype;
 original_invoice public.invoices%rowtype;
 new_invoice public.invoices%rowtype;
 saved_id uuid;
 operation_id uuid:=gen_random_uuid();
begin
 if p_kind not in ('cancel_invoice','replace_invoice','undo_invoice','restore_invoice') then
   raise exception 'Autorização restrita à alteração fiscal de NF';
 end if;
 select * into operator_row from public.users where id=p_actor;
 select * into manager_row from public.users where id=p_approver;
 if operator_row.id is null or operator_row.role not in ('general_manager','secretary')
    or manager_row.id is null or manager_row.role<>'general_manager' then
   raise exception 'Operador ou aprovador sem autorização';
 end if;
 select * into original_invoice from public.invoices
  where id=(p_data->>'id')::uuid;
 if original_invoice.id is null then raise exception 'NF não encontrada';end if;
 -- O financeiro antigo exige o perfil de gerente para executar a alteração.
 -- A trilha adicional abaixo registra o operador original de forma explícita.
 if p_kind='restore_invoice' then
  saved_id:=public.restore_billing_invoice(p_approver,p_data);
 else
  saved_id:=public.save_billing(p_approver,p_kind,p_data);
 end if;
 if p_kind='replace_invoice' then
  select * into new_invoice from public.invoices where id=saved_id;
 end if;
 insert into public.financial_logs(id,actor_id,actor_name,actor_email,kind,record_id)
 values(operation_id,operator_row.id,
  coalesce(nullif(operator_row.name,''),operator_row.email),
  operator_row.email,'manager_approval',original_invoice.id::text);
 insert into public.financial_log_changes(log_id,record_type,record_id,action,before_data,after_data)
 values(operation_id,'billing_manager_authorization',original_invoice.id::text,'INSERT',null,
  jsonb_build_object(
   'invoice_id',original_invoice.id,
   'invoice_number',original_invoice.invoice_number,
   'action_kind',p_kind,
   'authorized_by_id',manager_row.id,
   'authorized_by_name',coalesce(nullif(manager_row.name,''),manager_row.email),
   'operator_id',operator_row.id,
   'operator_name',coalesce(nullif(operator_row.name,''),operator_row.email),
   'operator_role',operator_row.role,
   'replacement_invoice_number',case when p_kind='replace_invoice'
    then new_invoice.invoice_number else null end
  ));
 return saved_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.save_company_finance(p_actor bigint, p_kind text, p_data jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare sid uuid:=coalesce(nullif(p_data->>'id','')::uuid,gen_random_uuid());entity uuid:=(p_data->>'billing_entity_id')::uuid;old_row public.company_expenses%rowtype;link uuid:=nullif(p_data->>'paid_by_doctor_entity_link_id','')::uuid;
begin
 perform pg_advisory_xact_lock(194701,2);
 if not exists(select 1 from public.users where id=p_actor and role='general_manager') then raise exception 'Acesso restrito à gerência';end if;
 if p_kind<>'expense' then raise exception 'Cadastro de associados descontinuado. Use os vínculos com médicos';end if;
 perform public.financial_operation(p_actor,'expense',sid::text);
 select * into old_row from public.company_expenses where id=sid;
 if old_row.id is not null and old_row.updated_at is distinct from (p_data->>'updated_at')::timestamptz then raise exception 'Registro alterado. Atualize';end if;
 if old_row.id is not null and old_row.billing_entity_id is distinct from entity then raise exception 'A entidade histórica não pode ser alterada';end if;
 if not exists(select 1 from public.billing_entities where id=entity and (active or old_row.id is not null)) then raise exception 'Entidade inativa ou inexistente';end if;
 if link is not null and not exists(select 1 from public.billing_doctor_entities where id=link and billing_entity_id=entity and (active or old_row.paid_by_doctor_entity_link_id=link)) then raise exception 'Selecione um vínculo médico ativo desta empresa';end if;
 if p_data->>'status'='PAGO' and (nullif(p_data->>'paid_at','') is null or (link is null and old_row.paid_by_associate_id is null)) then raise exception 'Pagamento exige data e médico vinculado';end if;
 if old_row.id is not null then
 update public.company_expenses set description=trim(p_data->>'description'),category=coalesce(p_data->>'category',''),supplier=coalesce(p_data->>'supplier',''),competence_date=(p_data->>'competence_date')::date,due_date=nullif(p_data->>'due_date','')::date,paid_at=case when p_data->>'status'='PAGO' then nullif(p_data->>'paid_at','')::date end,amount=(p_data->>'amount')::numeric,status=p_data->>'status',notes=p_data->>'notes',paid_by_doctor_entity_link_id=case when p_data->>'status'='PAGO' then link end where id=sid;
 else
 insert into public.company_expenses(id,billing_entity_id,description,category,supplier,competence_date,due_date,paid_at,amount,status,notes,paid_by_doctor_entity_link_id)
 values(sid,entity,trim(p_data->>'description'),coalesce(p_data->>'category',''),coalesce(p_data->>'supplier',''),(p_data->>'competence_date')::date,nullif(p_data->>'due_date','')::date,case when p_data->>'status'='PAGO' then nullif(p_data->>'paid_at','')::date end,(p_data->>'amount')::numeric,p_data->>'status',p_data->>'notes',case when p_data->>'status'='PAGO' then link end)
;
 end if;
 perform set_config('rn.operation','',true);perform set_config('rn.actor','',true);return sid;
end;$function$
;

CREATE OR REPLACE FUNCTION public.save_doctor_directory(p_actor bigint, p_kind text, p_data jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare sid text; old_row jsonb; result_row jsonb; old_agenda jsonb; new_agenda jsonb; org uuid;
begin
 perform pg_advisory_xact_lock(194701,1);
 org:=public.require_rn_agenda_actor_organization(p_actor);
 if not exists(select 1 from public.users where id=p_actor and role='general_manager') then raise exception 'Somente a gerência pode alterar o cadastro central'; end if;
 sid:=coalesce(nullif(p_data->>'id',''),gen_random_uuid()::text);
 if exists(select 1 from public.doctors where id=sid and organization_id<>org) then raise exception 'Médico não cadastrado'; end if;
 perform public.financial_operation(p_actor,'doctor',sid);
 if p_kind='doctor' then
  select to_jsonb(d) into old_row from public.doctors d where id=sid and organization_id=org;
  if old_row is not null and (old_row->>'updated_at')::timestamptz is distinct from (p_data->>'updated_at')::timestamptz then raise exception 'Médico alterado. Atualize a página'; end if;
  if coalesce(length(trim(p_data->>'name')),0)<2 then raise exception 'Informe o nome'; end if;
  if not coalesce(public.valid_medical_specialty(p_data->>'specialty'),false) then raise exception 'Selecione uma especialidade da lista';end if;
  if nullif(trim(p_data->>'crm'),'') is not null and exists(select 1 from public.doctors where organization_id=org and id<>sid and lower(trim(crm))=lower(trim(p_data->>'crm'))) then raise exception 'CRM já cadastrado. Use o médico existente'; end if;
  insert into public.doctors(id,organization_id,name,crm,specialty,category,active,scheduling_enabled,billing_enabled,invoice_enabled,updated_at,updated_by)
   values(sid,org,trim(p_data->>'name'),trim(coalesce(p_data->>'crm','')),trim(coalesce(p_data->>'specialty','')),case when public.is_anesthesiologist(p_data->>'specialty') then 'anesthetist' else 'doctor' end,coalesce((p_data->>'active')::boolean,true),coalesce((p_data->>'scheduling_enabled')::boolean,(old_row->>'scheduling_enabled')::boolean,true),coalesce((p_data->>'billing_enabled')::boolean,(old_row->>'billing_enabled')::boolean,true),coalesce((p_data->>'invoice_enabled')::boolean,(old_row->>'invoice_enabled')::boolean,true),clock_timestamp(),p_actor)
   on conflict(id) do update set name=excluded.name,crm=excluded.crm,specialty=excluded.specialty,category=excluded.category,active=excluded.active,scheduling_enabled=excluded.scheduling_enabled,billing_enabled=excluded.billing_enabled,invoice_enabled=excluded.invoice_enabled,updated_at=excluded.updated_at,updated_by=p_actor
   where public.doctors.organization_id=org
   returning to_jsonb(doctors.*) into result_row;
  if result_row is null then raise exception 'Médico não cadastrado'; end if;
 elsif p_kind='agenda' then
  if not exists(select 1 from public.doctors where id=sid and organization_id=org) then raise exception 'Médico não cadastrado'; end if;
  if not exists(select 1 from public.doctors where id=sid and organization_id=org and scheduling_enabled) then raise exception 'Agendamento não habilitado para o médico';end if;
  select to_jsonb(a) into old_row from public.doctor_agendas a where doctor_id=sid and organization_id=org;
  if old_row is not null and (old_row->>'updated_at')::timestamptz is distinct from (p_data->>'updated_at')::timestamptz then raise exception 'Agenda alterada. Atualize a página'; end if;
  if coalesce(p_data->>'workStart','')!~'^(0[0-9]|1[0-9]|2[0-3]):[0-5][0-9]$' or coalesce(p_data->>'workEnd','')!~'^(0[0-9]|1[0-9]|2[0-3]):[0-5][0-9]$' or p_data->>'workStart'>=p_data->>'workEnd' then raise exception 'Horário da agenda inválido'; end if;
  insert into public.doctor_agendas(doctor_id,organization_id,active,settings,updated_at,updated_by) values(sid,org,coalesce((p_data->>'active')::boolean,true),jsonb_build_object('workStart',p_data->>'workStart','workEnd',p_data->>'workEnd'),clock_timestamp(),p_actor)
  on conflict(doctor_id) do update set active=excluded.active,settings=excluded.settings,updated_at=excluded.updated_at,updated_by=p_actor returning to_jsonb(doctor_agendas.*) into result_row;
 else raise exception 'Operação inválida'; end if;
 if p_kind='doctor' and (result_row->>'scheduling_enabled')::boolean then
  select to_jsonb(a) into old_agenda from public.doctor_agendas a where a.doctor_id=sid and a.organization_id=org;
  if old_agenda is null or not coalesce((old_row->>'scheduling_enabled')::boolean,false) then
   insert into public.doctor_agendas(doctor_id,organization_id,active,settings,updated_at,updated_by)
    values(sid,org,true,jsonb_build_object('workStart','07:00','workEnd','19:00'),clock_timestamp(),p_actor)
    on conflict(doctor_id) do update set active=true,updated_at=clock_timestamp(),updated_by=p_actor
    returning to_jsonb(doctor_agendas.*) into new_agenda;
   insert into public.directory_audit(actor_id,kind,record_id,before_data,after_data,organization_id) values(p_actor,'agenda',sid,old_agenda,new_agenda,org);
  end if;
 end if;
 insert into public.directory_audit(actor_id,kind,record_id,before_data,after_data,organization_id) values(p_actor,p_kind,sid,old_row,result_row,org);
 update public.agenda_settings set revision=date_trunc('milliseconds',greatest(clock_timestamp(),revision+interval '1 millisecond')) where organization_id=org;
 if not found then raise exception 'Agenda da organização indisponível'; end if;
 perform set_config('rn.operation','',true);perform set_config('rn.actor','',true);return sid;
end;$function$
;

CREATE OR REPLACE FUNCTION public.save_doctor_with_access(p_actor bigint, p_kind text, p_data jsonb, p_access jsonb DEFAULT NULL::jsonb, p_credentials jsonb DEFAULT NULL::jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare did text; account_id bigint; access_data jsonb;
begin
 did:=public.save_doctor_directory(p_actor,p_kind,p_data);
 if p_access is not null then
  if p_kind<>'doctor' then raise exception 'Acesso pertence ao médico, não à agenda'; end if;
  select id into account_id from public.users where doctor_id=did;
  if (p_access->>'id')::bigint is distinct from account_id then raise exception 'Acesso alterado por outro usuário. Atualize'; end if;
  access_data:=p_access||jsonb_build_object('id',account_id,'doctor_id',did,'role','doctor','name',p_data->>'name');
  perform public.save_user_access(p_actor,access_data,p_credentials);
 end if;
 return did;
end;$function$
;

CREATE OR REPLACE FUNCTION public.save_doctor_with_access(p_actor bigint, p_kind text, p_data jsonb, p_access jsonb, p_credentials jsonb, p_org uuid)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ begin perform public.use_organization(p_actor,p_org); return public.save_doctor_with_access(p_actor,p_kind,p_data,p_access,p_credentials); end;$function$
;

CREATE OR REPLACE FUNCTION public.save_manual_attendance(p_actor bigint, p_data jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ begin perform public.billing_paused(); return null; end;$function$
;

CREATE OR REPLACE FUNCTION public.save_private_invoice(p_actor bigint, p_data jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r public.invoice_requests%rowtype;i public.invoices%rowtype;sid uuid;ids jsonb:=coalesce(p_data->'attendance_ids',p_data->'appointment_ids');
begin
 if not exists(select 1 from public.users where id=p_actor and role='general_manager') then raise exception 'Somente a gerência pode registrar NF';end if;
 select * into r from public.invoice_requests where id=nullif(p_data->>'request_id','')::uuid or (invoice_id=nullif(p_data->>'id','')::uuid and status='ISSUED') for update;
 if r.id is null or r.status='CANCELLED' then raise exception 'Selecione uma solicitação fiscal pendente';end if;
 if jsonb_typeof(ids) is distinct from 'array' or jsonb_array_length(ids)<>1 or ids->>0 is distinct from r.attendance_id then raise exception 'NF Particular exige exatamente um atendimento, fixado pela solicitação';end if;
 if p_data->>'billing_entity_id' is distinct from r.billing_entity_id::text then raise exception 'Empresa diferente da solicitação fiscal';end if;
 if nullif(trim(p_data->>'invoice_number'),'') is null or nullif(p_data->>'issue_date','') is null then raise exception 'Informe número da NF e data de emissão';end if;
 if r.status='ISSUED' then
  select * into i from public.invoices where id=r.invoice_id;
  if nullif(p_data->>'id','') is null then
   if i.invoice_number=trim(p_data->>'invoice_number') and i.issue_date=(p_data->>'issue_date')::date and i.total_amount is not distinct from nullif(p_data->>'total_amount','')::numeric and i.net_amount is not distinct from nullif(p_data->>'net_amount','')::numeric then return i.id;end if;raise exception 'Solicitação já emitida. Atualize a lista';end if;
  if i.updated_at is distinct from (p_data->>'updated_at')::timestamptz then raise exception 'NF alterada. Atualize a página';end if;
  update public.invoices set invoice_number=trim(p_data->>'invoice_number'),issue_date=(p_data->>'issue_date')::date,total_amount=nullif(p_data->>'total_amount','')::numeric,net_amount=nullif(p_data->>'net_amount','')::numeric,notes=nullif(trim(p_data->>'notes'),'') where id=i.id;return i.id;
 end if;
 if not exists(select 1 from public.billing_records where id=r.billing_record_id and billing_method='PARTICULAR' and payment_status='PAGO' and received_amount=r.received_amount_snapshot and paid_at=r.paid_at_snapshot and billing_entity_id=r.billing_entity_id) then raise exception 'Pagamento incompatível com a solicitação';end if;
 insert into public.invoices(billing_entity_id,invoice_number,issue_date,total_amount,net_amount,paid_at,payer,notes,recipient_type,recipient_kind,recipient_name,recipient_tax_id,recipient_address,patient_id,patient_name_snapshot)
 values(r.billing_entity_id,trim(p_data->>'invoice_number'),(p_data->>'issue_date')::date,nullif(p_data->>'total_amount','')::numeric,nullif(p_data->>'net_amount','')::numeric,r.paid_at_snapshot,r.taker_name,nullif(trim(p_data->>'notes'),''),'PARTICULAR',r.taker_kind,r.taker_name,r.taker_tax_id,r.taker_address,r.patient_id,r.patient_name_snapshot) returning id into sid;
 insert into public.invoice_billing_records(invoice_id,billing_record_id,received_amount) values(sid,r.billing_record_id,r.received_amount_snapshot);
 update public.invoice_requests set status='ISSUED',invoice_id=sid where id=r.id;return sid;
end;$function$
;

