CREATE OR REPLACE FUNCTION public.save_professional_invoice(p_actor bigint, p_data jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  role_name text;
  previous_invoice public.invoices%rowtype;
  target_invoice_id uuid := coalesce(nullif(p_data->>'id','')::uuid,gen_random_uuid());
  entity_id uuid := nullif(p_data->>'billing_entity_id','')::uuid;
  payer_value text := public.billing_payer_key(p_data->>'payer');
  record_id uuid;
  charge public.billing_records%rowtype;
  total numeric:=0;
  amount numeric;
begin
  perform pg_advisory_xact_lock(194701,4);
  select role into role_name from public.users where id=p_actor;
  if role_name is distinct from 'general_manager' then raise exception 'Somente a gerência pode gerenciar lotes'; end if;
  perform public.financial_operation(p_actor,'professional_invoice',target_invoice_id::text);
  if entity_id is null or not exists(select 1 from public.billing_entities where id=entity_id and active) then raise exception 'Entidade recebedora inativa ou inexistente'; end if;
  if payer_value='' or nullif(trim(p_data->>'invoice_number'),'') is null or nullif(p_data->>'issue_date','') is null then raise exception 'Preencha número, pagador e emissão'; end if;
  if jsonb_typeof(p_data->'record_ids') is distinct from 'array' or jsonb_array_length(p_data->'record_ids')=0 or jsonb_typeof(p_data->'item_amounts') is distinct from 'object' then raise exception 'Selecione as cobranças e informe cada valor'; end if;
  select * into previous_invoice from public.invoices where id=target_invoice_id for update;
  if previous_invoice.id is not null then
    if previous_invoice.status<>'ACTIVE' or previous_invoice.voided_at is not null then raise exception 'Documento histórico não pode ser editado'; end if;
    if previous_invoice.recipient_type<>'CONVENIO' then raise exception 'Documento não é NF de convênio'; end if;
    if previous_invoice.updated_at is distinct from nullif(p_data->>'updated_at','')::timestamptz then raise exception 'NF alterada. Atualize a página'; end if;
    if previous_invoice.paid_at is not null then raise exception 'NF já paga. Utilize o fluxo fiscal de correção ou substituição'; end if;
  end if;
  for record_id in select distinct value::uuid from jsonb_array_elements_text(p_data->'record_ids') loop
    select * into charge from public.billing_records where id=record_id for update;
    if not found or charge.billing_method<>'CONVENIO' or charge.settlement_mode='DIRECT' then raise exception 'Cobrança não elegível para NF de convênio'; end if;
    if charge.billing_entity_id<>entity_id then raise exception 'Todas as cobranças da NF devem usar a mesma entidade recebedora'; end if;
    if public.billing_payer_key(coalesce(charge.effective_payer_name_snapshot,charge.patient_insurance_snapshot,''))<>payer_value then raise exception 'Pagador efetivo diferente do lote'; end if;
    if exists(select 1 from public.invoice_billing_records ib where ib.billing_record_id=record_id and ib.invoice_id<>target_invoice_id and ib.is_active) then raise exception 'Cobrança já vinculada a outra NF'; end if;
    if not exists(select 1 from public.billing_doctor_entities where doctor_id=charge.professional_id and billing_entity_id=entity_id and active) then raise exception 'Profissional sem vínculo ativo com a entidade recebedora'; end if;
    amount:=nullif(p_data->'item_amounts'->>record_id::text,'')::numeric;
    if amount is null or amount<0 then raise exception 'Informe o valor de cada cobrança'; end if;
    total:=total+round(amount,2);
  end loop;
  if total+coalesce(nullif(p_data->>'closing_adjustment','')::numeric,0)<>round((p_data->>'net_amount')::numeric,2) then raise exception 'A soma dos itens e ajuste deve ser igual ao valor líquido'; end if;
  insert into public.invoices(id,billing_entity_id,invoice_number,payer,issue_date,total_amount,net_amount,paid_at,notes,recipient_type,closing_adjustment,closing_adjustment_reason,allocation_verified,payment_composition_verified,updated_at,updated_by)
  values(target_invoice_id,entity_id,trim(p_data->>'invoice_number'),payer_value,(p_data->>'issue_date')::date,nullif(p_data->>'total_amount','')::numeric,(p_data->>'net_amount')::numeric,nullif(p_data->>'paid_at','')::date,nullif(trim(p_data->>'notes'),''),'CONVENIO',coalesce(nullif(p_data->>'closing_adjustment','')::numeric,0),nullif(trim(p_data->>'closing_adjustment_reason'),''),true,false,clock_timestamp(),p_actor)
  on conflict(id) do update set billing_entity_id=excluded.billing_entity_id,invoice_number=excluded.invoice_number,payer=excluded.payer,issue_date=excluded.issue_date,total_amount=excluded.total_amount,net_amount=excluded.net_amount,paid_at=excluded.paid_at,notes=excluded.notes,closing_adjustment=excluded.closing_adjustment,closing_adjustment_reason=excluded.closing_adjustment_reason,updated_at=excluded.updated_at,updated_by=excluded.updated_by;
  update public.billing_records set payment_status='PENDENTE',updated_at=clock_timestamp(),updated_by=p_actor where id in(select ib.billing_record_id from public.invoice_billing_records ib where ib.invoice_id=target_invoice_id);
  delete from public.invoice_billing_records ib where ib.invoice_id=target_invoice_id and not (ib.billing_record_id in(select value::uuid from jsonb_array_elements_text(p_data->'record_ids')));
  for record_id in select distinct value::uuid from jsonb_array_elements_text(p_data->'record_ids') loop
    amount:=(p_data->'item_amounts'->>record_id::text)::numeric;
    insert into public.invoice_billing_records(invoice_id,billing_record_id,received_amount,is_active)
      values(target_invoice_id,record_id,round(amount,2),true)
      on conflict(invoice_id,billing_record_id) do update set received_amount=excluded.received_amount,is_active=true;
  end loop;
  update public.billing_records set payment_status=case when nullif(p_data->>'paid_at','') is null then 'PENDENTE' else 'PAGO' end,received_amount=null,paid_at=null,invoice_number=null,updated_at=clock_timestamp(),updated_by=p_actor where id in(select value::uuid from jsonb_array_elements_text(p_data->'record_ids'));
  if nullif(p_data->>'paid_at','') is not null then
    if jsonb_typeof(p_data->'payment_parts') is distinct from 'array' then raise exception 'Informe as formas de pagamento'; end if;
    perform public.write_payment_parts(null,target_invoice_id,p_data->'payment_parts');
    update public.invoices set payment_composition_verified=true where id=target_invoice_id;
  else
    delete from public.payment_parts where invoice_id=target_invoice_id;
  end if;
  return target_invoice_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.save_user_access(p_actor bigint, p_data jsonb, p_credentials jsonb DEFAULT NULL::jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare uid bigint:=nullif(p_data->>'id','')::bigint; old_account public.users%rowtype; did text:=nullif(p_data->>'doctor_id',''); email_value text:=lower(trim(p_data->>'email')); role_value text:=p_data->>'role'; grant_id text; org uuid; desired_active boolean;
begin
 perform pg_advisory_xact_lock(194701,1);
 org:=public.actor_organization_id(p_actor);
 if not exists(
  select 1 from public.users actor
  join public.organization_memberships membership on membership.user_id=actor.id
  where actor.id=p_actor and actor.role='general_manager' and actor.active
    and membership.organization_id=org and membership.role='general_manager' and membership.active
 ) then raise exception 'Acesso restrito à gerência'; end if;
 if role_value not in ('general_manager','secretary','doctor') or role_value is null or email_value is null or email_value !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' or length(email_value)>254 then raise exception 'Dados de acesso inválidos'; end if;
 if role_value='doctor' and (did is null or not exists(select 1 from public.doctors where id=did and organization_id=org)) then raise exception 'Selecione um médico existente'; end if;
 if role_value<>'doctor' then did:=null; end if;
 if uid=p_actor and role_value<>'general_manager' then raise exception 'Outro gerente deve alterar seu nível de acesso'; end if;
 if uid is not null then
  select * into old_account from public.users where id=uid for update;
  if not found then raise exception 'Usuário inexistente'; end if;
  if not exists(select 1 from public.organization_memberships where organization_id=org and user_id=uid)
      or exists(select 1 from public.organization_memberships where user_id=uid and organization_id<>org)
   then raise exception 'Conta fora da organização atual'; end if;
  if p_data ? 'updated_at' and old_account.updated_at is distinct from (p_data->>'updated_at')::timestamptz then raise exception 'Acesso alterado por outro usuário. Atualize'; end if;
 end if;
 if p_data ? 'active' and jsonb_typeof(p_data->'active') <> 'boolean' then raise exception 'Situação de acesso inválida'; end if;
 if uid is null and p_data ? 'active' then raise exception 'Novo acesso deve começar ativo'; end if;
 desired_active:=case when uid is null then true when p_data ? 'active' then (p_data->>'active')::boolean else old_account.active end;
 if uid=p_actor and not desired_active then raise exception 'Outro gerente deve desativar seu acesso'; end if;
 if exists(select 1 from public.users where lower(email)=email_value and id is distinct from uid) then raise exception 'Já existe uma conta com este e-mail'; end if;
 if did is not null and exists(select 1 from public.users where doctor_id=did and id is distinct from uid) then raise exception 'Este médico já possui um acesso'; end if;
 if uid is null and p_credentials is null then raise exception 'Informe uma senha inicial'; end if;
 if p_credentials is not null and (coalesce(p_credentials->>'hash','') !~ '^pbkdf2-sha256\$600000\$[A-Za-z0-9+/=]+$' or length(coalesce(p_credentials->>'salt',''))<20) then raise exception 'Credencial inválida'; end if;
 if p_data ? 'agendaIds' then
  if jsonb_typeof(p_data->'agendaIds') is distinct from 'array' then raise exception 'Agendas inválidas'; end if;
  for grant_id in select jsonb_array_elements_text(p_data->'agendaIds') loop
   if not exists(select 1 from public.doctors where id=grant_id and organization_id=org) then raise exception 'Agenda inexistente'; end if;
  end loop;
 end if;
 if uid is null then
  insert into public.users(email,name,role,doctor_id,password_hash,password_salt,active) values(email_value,coalesce(p_data->>'name',''),role_value,did,p_credentials->>'hash',p_credentials->>'salt',true) returning id into uid;
  insert into public.organization_memberships(organization_id,user_id,role,active) values(org,uid,role_value,true);
 else
  update public.users set email=email_value,name=coalesce(p_data->>'name',''),role=role_value,doctor_id=did,active=desired_active,password_hash=coalesce(p_credentials->>'hash',password_hash),password_salt=coalesce(p_credentials->>'salt',password_salt),updated_at=clock_timestamp() where id=uid;
  update public.organization_memberships set role=role_value,active=desired_active,updated_at=clock_timestamp() where organization_id=org and user_id=uid;
  if not found then raise exception 'Vínculo da organização não encontrado'; end if;
 end if;
 delete from public.sessions where user_id=uid;
 if p_data ? 'agendaIds' or role_value='general_manager' then
  delete from public.agenda_access where user_id=uid and organization_id=org;
  if role_value<>'general_manager' then
   insert into public.agenda_access(user_id,professional_id,organization_id) select uid,value,org from (select distinct jsonb_array_elements_text(p_data->'agendaIds') value) x;
  end if;
 end if;
 if did is not null and not exists(select 1 from public.agenda_access where user_id=uid and professional_id=did) then insert into public.agenda_access(user_id,professional_id,organization_id) values(uid,did,org); end if;
 insert into public.directory_audit(actor_id,kind,record_id,before_data,after_data,organization_id) values(p_actor,'user_access',uid::text,case when old_account.id is not null then jsonb_build_object('email',old_account.email,'role',old_account.role,'doctor_id',old_account.doctor_id,'active',old_account.active) end,jsonb_build_object('email',email_value,'role',role_value,'doctor_id',did,'active',desired_active,'password_changed',p_credentials is not null,'agendaIds',(select coalesce(jsonb_agg(professional_id),'[]') from public.agenda_access where user_id=uid)),org);
 return uid;
end;$function$
;

CREATE OR REPLACE FUNCTION public.save_user_access(p_actor bigint, p_data jsonb, p_credentials jsonb, p_org uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ begin perform public.use_organization(p_actor,p_org); return public.save_user_access(p_actor,p_data,p_credentials); end;$function$
;

CREATE OR REPLACE FUNCTION public.session_context(p_token_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
 v_user public.users%rowtype; v_session public.sessions%rowtype; v_org public.organizations%rowtype; v_account public.accounts%rowtype;
 v_services jsonb:='{"scheduling_enabled":false,"billing_enabled":false,"invoice_enabled":false}'::jsonb;
 v_agendas text[]:='{}'; v_orgs jsonb;
begin
 if p_token_hash is null or length(p_token_hash)>100 then return null; end if;
 select s.* into v_session from public.sessions s where s.token_hash=p_token_hash and s.expires_at>now();
 if not found then return null; end if;
 select u.* into v_user from public.users u where u.id=v_session.user_id;
 if not found or not v_user.active or v_user.role not in ('general_manager','secretary','doctor') then return null; end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',o.id,'slug',o.slug,'name',o.name,'kind',o.kind) order by o.name),'[]'::jsonb) into v_orgs
  from public.organization_memberships m join public.organizations o on o.id=m.organization_id and o.active
  join public.accounts a on a.id=o.account_id and a.status='active'
  where m.user_id=v_user.id and m.active and m.role=v_user.role;
 select o.* into v_org from public.organizations o
  where o.id=coalesce(
   case when public.membership_organization_ok(v_user.id,v_session.organization_id) then v_session.organization_id end,
   case when public.membership_organization_ok(v_user.id,v_user.last_organization_id) then v_user.last_organization_id end,
   (select (x->>'id')::uuid from jsonb_array_elements(v_orgs) x limit 1));
 if not found then return null; end if;
 select a.* into v_account from public.accounts a where a.id=v_org.account_id;
 if v_user.role='doctor' and v_user.doctor_id is not null then
  select jsonb_build_object('scheduling_enabled',d.scheduling_enabled,'billing_enabled',d.billing_enabled,'invoice_enabled',d.invoice_enabled)
   into v_services from public.doctors d where d.id=v_user.doctor_id and d.active and d.organization_id=v_org.id;
  v_services:=coalesce(v_services,'{"scheduling_enabled":false,"billing_enabled":false,"invoice_enabled":false}'::jsonb);
 end if;
 if v_user.role<>'general_manager' then
  select coalesce(array_agg(distinct x),'{}') into v_agendas from (
   select a.professional_id::text x from public.agenda_access a join public.doctors d on d.id=a.professional_id and d.organization_id=v_org.id
    where a.user_id=v_user.id and a.organization_id=v_org.id
   union select v_user.doctor_id where v_user.role='doctor' and v_user.doctor_id is not null
    and exists(select 1 from public.doctors d where d.id=v_user.doctor_id and d.organization_id=v_org.id)
  ) t;
 end if;
 return jsonb_build_object(
  'account',jsonb_build_object('id',v_user.id,'email',v_user.email,'name',v_user.name,'role',v_user.role,'doctorId',v_user.doctor_id),
  'organization',jsonb_build_object('id',v_org.id,'slug',v_org.slug,'name',v_org.name,'kind',v_org.kind),
  'organizations',v_orgs,
  'customer',jsonb_build_object('id',v_account.id,'name',v_account.name,'isOwner',v_account.owner_user_id=v_user.id,
    'maxOrganizations',v_account.max_organizations,
    'organizationCount',(select count(*) from public.organizations where account_id=v_account.id and active)),
  'services',v_services,
  'agendaIds',to_jsonb(v_agendas));
end;$function$
;

CREATE OR REPLACE FUNCTION public.signup_account(p_email text, p_name text, p_hash text, p_salt text, p_org_name text, p_org_kind text, p_terms_version text, p_token_hash text)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_email text:=lower(btrim(p_email)); v_user bigint; v_acc uuid; v_org uuid:=gen_random_uuid();
begin
 perform pg_advisory_xact_lock(194701,8);
 if v_email is null or v_email !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' or length(v_email)>254 then raise exception 'E-mail inválido'; end if;
 if coalesce(char_length(btrim(p_name)),0) not between 2 and 120 then raise exception 'Informe seu nome'; end if;
 if coalesce(char_length(btrim(p_org_name)),0) not between 2 and 120 then raise exception 'Informe o nome da organização'; end if;
 if p_org_kind not in ('MANAGEMENT_COMPANY','CLINIC','SOLO_DOCTOR') then raise exception 'Tipo de organização inválido'; end if;
 if not public.valid_password_credentials(p_hash,p_salt) then raise exception 'Credencial inválida'; end if;
 if coalesce(btrim(p_terms_version),'')='' then raise exception 'Aceite os termos de uso'; end if;
 if exists(select 1 from public.users where lower(email)=v_email) then raise exception 'Já existe uma conta com este e-mail'; end if;
 insert into public.users(email,name,role,active,password_hash,password_salt,email_verified_at,terms_version,terms_accepted_at)
  values(v_email,btrim(p_name),'general_manager',true,p_hash,p_salt,null,btrim(p_terms_version),now()) returning id into v_user;
 insert into public.accounts(name,owner_user_id,plan,max_organizations) values(btrim(p_org_name),v_user,'trial',1) returning id into v_acc;
 insert into public.organizations(id,slug,name,kind,active,account_id) values(v_org,public.organization_slug(p_org_name,v_org),btrim(p_org_name),p_org_kind,true,v_acc);
 insert into public.agenda_settings(organization_id) values(v_org);
 insert into public.organization_memberships(organization_id,user_id,role,active) values(v_org,v_user,'general_manager',true);
 insert into public.auth_tokens(token_hash,kind,user_id,email,organization_id,expires_at) values(p_token_hash,'verify_email',v_user,v_email,v_org,now()+interval '48 hours');
 return v_user;
end;$function$
;

CREATE OR REPLACE FUNCTION public.snapshot_appointment_insurance()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare collection text;a jsonb;previous jsonb;result jsonb;insurance text;patient jsonb;
begin
 foreach collection in array array['appointments','cancelledAppointments'] loop
 result:='[]';
 for a in select value from jsonb_array_elements(coalesce(new.payload->collection,'[]')) loop
 previous:=null;
 if tg_op='UPDATE' then select value into previous from jsonb_array_elements(coalesce(old.payload->'appointments','[]')||coalesce(old.payload->'cancelledAppointments','[]')) where value->>'id'=a->>'id' limit 1;end if;
 if a->>'insurance' is null then
  select t.insurance into insurance from public.attendances t where t.appointment_id=a->>'id';
  if insurance is null then
   if previous is not null then select value into patient from jsonb_array_elements(coalesce(old.payload->'patients','[]')) where value->>'id'=previous->>'patientId';
   else select value into patient from jsonb_array_elements(coalesce(new.payload->'patients','[]')) where value->>'id'=a->>'patientId';end if;
  end if;
  a:=a||jsonb_build_object('insurance',coalesce(previous->>'insurance',insurance,patient->>'insurance',''));
 end if;
 if public.appointment_billing_method(a)='CONVENIO' and nullif(trim(a->>'insurance'),'') is null and
 (previous is null or previous->>'insurance' is distinct from a->>'insurance' or public.appointment_billing_method(previous) is distinct from public.appointment_billing_method(a)) then raise exception 'Informe o convênio do atendimento';end if;
 result:=result||jsonb_build_array(a);
 end loop;
 new.payload:=jsonb_set(new.payload,array[collection],result);
 end loop;return new;
end;$function$
;

CREATE OR REPLACE FUNCTION public.stamp_patient_authorship()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare p jsonb;previous jsonb;result jsonb:='[]';actor bigint:=nullif(current_setting('rn.actor',true),'')::bigint;
begin
 for p in select value from jsonb_array_elements(coalesce(new.payload->'patients','[]')) loop
  previous:=null;
  if tg_op='UPDATE' then select value into previous from jsonb_array_elements(coalesce(old.payload->'patients','[]')) where value->>'id'=p->>'id';end if;
  if previous is null or (previous-'created_by'-'created_at'-'updated_by'-'updated_at') is distinct from (p-'created_by'-'created_at'-'updated_by'-'updated_at') then
   if actor is null then raise exception 'Cadastro de paciente exige autoria';end if;
   p:=p||jsonb_build_object('created_by',case when previous is null then to_jsonb(actor) else previous->'created_by' end,'created_at',case when previous is null then to_jsonb(clock_timestamp()) else previous->'created_at' end,'updated_by',actor,'updated_at',clock_timestamp());
  else p:=(p-'created_by'-'created_at'-'updated_by'-'updated_at')||(select coalesce(jsonb_object_agg(key,value),'{}') from jsonb_each(previous) where key in('created_by','created_at','updated_by','updated_at'));
  end if;
  result:=result||jsonb_build_array(p);
 end loop;
 new.payload:=jsonb_set(new.payload,'{patients}',result);return new;
end;$function$
;

CREATE OR REPLACE FUNCTION public.submit_agenda_suggestion(p_request jsonb, p_notification jsonb, p_audit jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  request_id text := nullif(p_request->>'id','');
  requester bigint := nullif(p_request->>'requested_by','')::bigint;
  action_name text := p_request->>'action';
  appointment_key text := nullif(p_request->>'appointment_id','');
  existing_id text;
BEGIN
  IF request_id IS NULL OR requester IS NULL OR action_name NOT IN ('create','update','delete')
     OR appointment_key IS NULL OR p_notification->>'request_id' IS DISTINCT FROM request_id
     OR p_audit->'metadata'->>'requestId' IS DISTINCT FROM request_id THEN
    RAISE EXCEPTION 'Solicitação de agenda inválida';
  END IF;

  -- Também impede solicitações pendentes duplicadas em envios simultâneos.
  PERFORM pg_advisory_xact_lock(194701,3);
  SELECT id INTO existing_id
  FROM public.agenda_requests
  WHERE requested_by=requester AND action=action_name
    AND appointment_id IS NOT DISTINCT FROM appointment_key AND status='pending'
  ORDER BY created_at DESC LIMIT 1;
  IF existing_id IS NOT NULL THEN
    RETURN existing_id;
  END IF;

  INSERT INTO public.agenda_requests
    (id,professional_id,appointment_id,action,proposed_payload,previous_payload,requested_by,created_at)
  VALUES
    (request_id,p_request->>'professional_id',appointment_key,action_name,
     NULLIF(p_request->'proposed_payload','null'::jsonb),NULLIF(p_request->'previous_payload','null'::jsonb),requester,
     (p_request->>'created_at')::timestamptz);

  INSERT INTO public.notifications
    (id,user_id,type,request_id,message,created_at)
  VALUES
    (p_notification->>'id',requester,'request_sent',request_id,
     'Alteração de agenda enviada.',(p_request->>'created_at')::timestamptz);

  INSERT INTO public.audit_logs
    (id,actor_user_id,actor_name,actor_role,action,professional_id,appointment_id,
     patient_id,description,metadata,created_at)
  VALUES
    (p_audit->>'id',requester,p_audit->>'actor_name',p_audit->>'actor_role',
     'request_created',p_audit->>'professional_id',nullif(p_audit->>'appointment_id',''),
     nullif(p_audit->>'patient_id',''),p_audit->>'description',p_audit->'metadata',
     (p_request->>'created_at')::timestamptz);

  RETURN request_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.submit_agenda_suggestion(p_request jsonb, p_notification jsonb, p_audit jsonb, p_org uuid)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ begin perform public.use_organization(nullif(p_request->>'requested_by','')::bigint,p_org); return public.submit_agenda_suggestion(p_request,p_notification,p_audit); end;$function$
;

CREATE OR REPLACE FUNCTION public.switch_session_organization(p_token_hash text, p_org uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_user bigint;
begin
 select user_id into v_user from public.sessions where token_hash=p_token_hash and expires_at>now();
 if v_user is null or not public.membership_organization_ok(v_user,p_org) then raise exception 'Acesso à organização negado'; end if;
 update public.sessions set organization_id=p_org where token_hash=p_token_hash;
 update public.users set last_organization_id=p_org where id=v_user;
 return true;
end;$function$
;

CREATE OR REPLACE FUNCTION public.sync_appointment_attendance()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare t public.attendances%rowtype; owner text; historical_insurance text;
begin
 if coalesce(current_setting('rn.agenda_migration',true),'')='on' then return null; end if;
 select * into t from public.attendances where appointment_id=new.id;
 if new.status<>'realized' and t.id is null then return null; end if;
 owner:=coalesce(t.doctor_id,new.professional_id,new.anesthetist_id);
 historical_insurance:=coalesce(new.insurance,t.insurance,(select insurance from public.patients where id=new.patient_id),'');
 if t.id is not null and tg_op='UPDATE' and old.insurance is not distinct from new.insurance
   and exists(select 1 from public.billing_records b join public.invoice_billing_records ib on ib.billing_record_id=b.id where b.attendance_id=t.id) then
  historical_insurance:=t.insurance;
 end if;
 if t.id is null then
  insert into public.attendances(id,appointment_id,origin,patient_id,doctor_id,date,procedure,insurance,billing_method,status,organization_id)
  values(new.id,new.id,'AGENDA',new.patient_id,owner,new.date,new.procedure,historical_insurance,new.billing_method,new.status,new.organization_id);
 elsif (t.patient_id,t.date,t.procedure,t.insurance,t.billing_method,t.status)
   is distinct from (new.patient_id,new.date,new.procedure,historical_insurance,coalesce(new.billing_method,t.billing_method),new.status) then
  update public.attendances set patient_id=new.patient_id,date=new.date,procedure=new.procedure,insurance=historical_insurance,
   billing_method=coalesce(new.billing_method,t.billing_method),status=new.status where id=t.id;
 end if;
 return null;
end;$function$
;

CREATE OR REPLACE FUNCTION public.sync_financial_attendances()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare a jsonb;patient jsonb;owner text;t public.attendances%rowtype;previous jsonb;historical_insurance text;
begin
 for a in select value from jsonb_array_elements(coalesce(new.payload->'appointments','[]')||coalesce(new.payload->'cancelledAppointments','[]')) loop
  select * into t from public.attendances where appointment_id=a->>'id';
  if a->>'status'<>'realized' and t.id is null then continue;end if;
  select value into patient from jsonb_array_elements(coalesce(new.payload->'patients','[]')) where value->>'id'=a->>'patientId';
  owner:=coalesce(t.doctor_id,nullif(a->>'doctorId',''),a->>'anesthetistId');
  previous:=null;
  if tg_op='UPDATE' then select value into previous from jsonb_array_elements(coalesce(old.payload->'appointments','[]')||coalesce(old.payload->'cancelledAppointments','[]')) where value->>'id'=a->>'id' limit 1;end if;
  historical_insurance:=coalesce(a->>'insurance',t.insurance,patient->>'insurance','');
  -- Legacy UI saved empty insurance even on already linked NFs. Preserve established
  -- financial history on unrelated edits without filling explicit empty clinical snapshots.
  if t.id is not null and previous->>'insurance' is not distinct from a->>'insurance'
    and exists(select 1 from public.billing_records b join public.invoice_billing_records ib on ib.billing_record_id=b.id where b.attendance_id=t.id)
  then historical_insurance:=t.insurance;end if;

  if t.id is null then
   insert into public.attendances(id,appointment_id,origin,patient_id,doctor_id,date,procedure,insurance,billing_method,status) values(a->>'id',a->>'id','AGENDA',nullif(a->>'patientId',''),owner,(a->>'date')::date,coalesce(a->>'procedure','Procedimento'),historical_insurance,public.appointment_billing_method(a),a->>'status');
  elsif (t.patient_id,t.date,t.procedure,t.insurance,t.billing_method,t.status) is distinct from (nullif(a->>'patientId',''),(a->>'date')::date,coalesce(a->>'procedure','Procedimento'),historical_insurance,public.appointment_billing_method(a,t.billing_method),a->>'status') then
   update public.attendances set patient_id=nullif(a->>'patientId',''),date=(a->>'date')::date,procedure=coalesce(a->>'procedure','Procedimento'),insurance=historical_insurance,billing_method=public.appointment_billing_method(a,t.billing_method),status=a->>'status' where id=t.id;
  end if;
 end loop;
 return new;
end;$function$
;

CREATE OR REPLACE FUNCTION public.touch_monitor_heartbeat(p_name text, p_ok boolean, p_details jsonb)
 RETURNS void
 LANGUAGE sql
 SET search_path TO ''
AS $function$
 insert into public.monitor_heartbeats(name,last_run_at,ok,details) values(p_name,now(),p_ok,coalesce(p_details,'{}'::jsonb))
 on conflict (name) do update set last_run_at=now(),ok=excluded.ok,details=excluded.details
$function$
;

CREATE OR REPLACE FUNCTION public.unlock_billing_month(p_actor bigint, p_entity uuid, p_month text, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 rn_org_id uuid;
 first_day date;
 latest public.billing_monthly_closing_events%rowtype;
 event_id uuid;
begin
 rn_org_id:=public.require_rn_agenda_actor_organization(p_actor);
 if not exists(select 1 from public.billing_entities where id=p_entity and organization_id=rn_org_id) then raise exception 'Entidade recebedora não encontrada na organização';end if;
 if not exists(select 1 from public.users where id=p_actor and role='general_manager' and active) then
   raise exception 'Somente o Gerente Geral pode desbloquear';
 end if;
 if p_month is null or p_month !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' then
   raise exception 'Competência inválida';
 end if;
 if length(trim(coalesce(p_reason,''))) not between 5 and 2000 then
   raise exception 'Justifique o desbloqueio (mínimo 5 caracteres)';
 end if;
 first_day:=(p_month||'-01')::date;
 perform pg_advisory_xact_lock(hashtext(p_entity::text||p_month)::bigint);
 select * into latest from public.billing_monthly_closing_events
   where billing_entity_id=p_entity and organization_id=rn_org_id and competence_month=first_day
   order by event_number desc limit 1;
 if latest.id is not null then
   if latest.event_type<>'CLOSED' then raise exception 'Competência já desbloqueada';end if;
 elsif not exists(select 1 from public.billing_monthly_closings
   where billing_entity_id=p_entity and organization_id=rn_org_id and competence_month=first_day) then
   raise exception 'A competência ainda não foi fechada';
 end if;
 insert into public.billing_monthly_closing_events(
   billing_entity_id,competence_month,event_type,notes,actor_id)
 values(p_entity,first_day,'UNLOCKED',trim(p_reason),p_actor)
 returning id into event_id;
 return event_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.update_organization(p_actor bigint, p_org uuid, p_name text, p_kind text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r public.organizations%rowtype;
begin
 perform public.require_organization_manager(p_actor,p_org);
 if coalesce(char_length(btrim(p_name)),0) not between 2 and 120 then raise exception 'Informe o nome da organização'; end if;
 if p_kind not in ('MANAGEMENT_COMPANY','CLINIC','SOLO_DOCTOR') then raise exception 'Tipo de organização inválido'; end if;
 update public.organizations set name=btrim(p_name),kind=p_kind,updated_at=clock_timestamp() where id=p_org returning * into r;
 perform set_config('rn.organization','',true);
 return jsonb_build_object('id',r.id,'name',r.name,'kind',r.kind);
end;$function$
;

CREATE OR REPLACE FUNCTION public.update_pending_invoice_request(p_actor bigint, p_data jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ begin perform public.billing_paused(); return null; end;$function$
;

CREATE OR REPLACE FUNCTION public.use_organization(p_actor bigint, p_org uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if p_org is null then raise exception 'Selecione a organização'; end if;
 perform set_config('rn.organization',p_org::text,true);
 return public.actor_organization_id(p_actor);
end;$function$
;

CREATE OR REPLACE FUNCTION public.user_organization_id(p_user bigint)
 RETURNS uuid
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
 select organization_id from public.organization_memberships where user_id=p_user
 order by active desc, updated_at desc nulls last limit 1
$function$
;

CREATE OR REPLACE FUNCTION public.valid_cpf(v text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare s text:=regexp_replace(coalesce(v,''),'[^0-9]','','g');n int;k int;t int;
begin
 if length(s)<>11 or s=repeat(substr(s,1,1),11) then return false;end if;
 for n in 10..11 loop t:=0;for k in 1..n-1 loop t:=t+substr(s,k,1)::int*(n+1-k);end loop;t:=(t*10)%11;if t=10 then t:=0;end if;if t<>substr(s,n,1)::int then return false;end if;end loop;return true;
end;$function$
;

CREATE OR REPLACE FUNCTION public.valid_medical_specialty(value text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$ select value=any(array['Acupuntura','Alergia e Imunologia','Anestesiologia','Angiologia','Cardiologia','Cirurgia Cardiovascular','Cirurgia da Mão','Cirurgia de Cabeça e Pescoço','Cirurgia do Aparelho Digestivo','Cirurgia Geral','Cirurgia Oncológica','Cirurgia Pediátrica','Cirurgia Plástica','Cirurgia Torácica','Cirurgia Vascular','Clínica Médica','Coloproctologia','Dermatologia','Endocrinologia e Metabologia','Endoscopia','Gastroenterologia','Genética Médica','Geriatria','Ginecologia e Obstetrícia','Hematologia e Hemoterapia','Homeopatia','Infectologia','Mastologia','Medicina de Emergência','Medicina de Família e Comunidade','Medicina do Trabalho','Medicina do Tráfego','Medicina Esportiva','Medicina Física e Reabilitação','Medicina Intensiva','Medicina Legal e Perícia Médica','Medicina Nuclear','Medicina Preventiva e Social','Nefrologia','Neurocirurgia','Neurologia','Nutrologia','Oftalmologia','Oncologia Clínica','Ortopedia e Traumatologia','Otorrinolaringologia','Patologia','Patologia Clínica/Medicina Laboratorial','Pediatria','Pneumologia','Psiquiatria','Radiologia e Diagnóstico por Imagem','Radioterapia','Reumatologia','Urologia']) $function$
;

CREATE OR REPLACE FUNCTION public.valid_password_credentials(p_hash text, p_salt text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
 select coalesce(p_hash,'') ~ '^pbkdf2-sha256\$600000\$[A-Za-z0-9+/=]+$' and length(coalesce(p_salt,''))>=20
$function$
;

CREATE OR REPLACE FUNCTION public.validate_user_doctor_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if new.role<>'doctor' and new.doctor_id is not null then raise exception 'Somente usuário médico pode ter identidade profissional'; end if;
 if new.role='doctor' and new.doctor_id is null then
  if tg_op='INSERT' then raise exception 'Selecione o médico deste acesso'; end if;
  if old.role is distinct from new.role or old.doctor_id is distinct from new.doctor_id then raise exception 'Selecione o médico deste acesso'; end if;
 end if;
 return new;
end;$function$
;

CREATE OR REPLACE FUNCTION public.write_payment_parts(p_record uuid, p_invoice uuid, p_parts jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare part jsonb;
begin
 if jsonb_typeof(p_parts) is distinct from 'array' or jsonb_array_length(p_parts)=0 then raise exception 'Informe as formas de pagamento';end if;
 delete from public.payment_parts where (p_record is not null and billing_record_id=p_record) or (p_invoice is not null and invoice_id=p_invoice);
 for part in select value from jsonb_array_elements(p_parts) loop
  if jsonb_typeof(part->'amount') is distinct from 'number' then raise exception 'Valor da forma de pagamento obrigatório';end if;
  insert into public.payment_parts(billing_record_id,invoice_id,method,amount,installments,notes)
  values(p_record,p_invoice,part->>'method',round((part->>'amount')::numeric,2),nullif(part->>'installments','')::integer,nullif(trim(part->>'notes'),''));
 end loop;
end;$function$
;

