comment on column public.billing_records.invoice_number is 'Deprecated historical compatibility. New documents use invoices. Legacy records require explicit review; fiscal identity is never inferred from current patient data.';
comment on column public.billing_records.payment_composition_verified is 'Confirmed composition for a paid record; false after reversal or for unreviewed legacy receipts.';
comment on column public.company_expenses.paid_by_associate_id is 'DEPRECATED immutable legacy payer, retained only for historical compatibility.';
comment on column public.doctors.category is 'DEPRECATED compatibility projection derived from specialty. Never user-editable or a business discriminator.';
comment on column public.invoice_billing_records.received_amount is 'Optional actual individual receipt from payer statement. Never allocated from invoice totals.';
comment on column public.invoices.allocation_verified is 'False only for pre-migration documents. Explicit review required; no historical allocation inferred.';
comment on column public.invoices.payment_composition_verified is 'Confirmed composition for a paid invoice; false after payment reversal or for unreviewed legacy receipts.';
comment on column public.invoices.voided_at is 'Internal mistaken entry undone. Distinct from fiscal cancellation; document and links retained for audit.';
comment on function public.save_professional_charge(p_actor bigint, p_data jsonb) is 'Cobrança profissional e, em pagamento PARTICULAR, solicitação fiscal atômica por billing_record_id';
comment on table public.company_associates is 'DEPRECATED readonly historical compatibility. New expenses reference billing_doctor_entities.';

